#[test]
fn option_result_literal_methods_runtime_payloads_decline() {
    let cases = [
        (
            "coretests/option/compose_runtime_some_pred.rs",
            r#"
                fn runtime() -> i32 { std::env::args().count() as i32 }

                #[test]
                fn t_runtime_some_pred() {
                    assert!(Some(runtime()).is_some());
                }
            "#,
        ),
        (
            "coretests/result/compose_runtime_ok_pred.rs",
            r#"
                fn runtime() -> i32 { std::env::args().count() as i32 }

                #[test]
                fn t_runtime_ok_pred() {
                    assert!(Ok::<i32, i32>(runtime()).is_ok());
                }
            "#,
        ),
        (
            "coretests/option/compose_runtime_unwrap_or.rs",
            r#"
                fn runtime() -> i32 { std::env::args().count() as i32 }

                #[test]
                fn t_runtime_unwrap_or() {
                    assert_eq!(Some(runtime()).unwrap_or(9), 9);
                }
            "#,
        ),
        (
            "coretests/result/compose_runtime_unwrap_or.rs",
            r#"
                fn runtime() -> i32 { std::env::args().count() as i32 }

                #[test]
                fn t_runtime_unwrap_or() {
                    assert_eq!(Ok::<i32, i32>(runtime()).unwrap_or(9), 9);
                }
            "#,
        ),
        (
            "coretests/option/compose_runtime_payload_chain.rs",
            r#"
                fn runtime() -> i32 { std::env::args().count() as i32 }

                #[test]
                fn t_runtime_payload_chain() {
                    assert_eq!(Some(runtime()).map(|x| x + 1).unwrap_or(9), 9);
                }
            "#,
        ),
    ];

    for (path, src) in cases {
        let out = lift_file(&parse(src), path);
        assert_eq!(
            out.assertions_lifted, 0,
            "{path} has a runtime payload; literal-method sugar must propagate Hit/refuse instead of inventing a literal assertion"
        );
        assert!(
            out.skip_reasons
                .iter()
                .any(|reason| reason.contains("runtime Option/Result payload, not literal")),
            "{path} should name-refuse runtime monadic payloads: {:?}",
            out.skip_reasons
        );
    }
}

// Signed/unsigned boundary teeth: `i8::try_from(200u16)` overflows (200 > 127) ->
// Err; `u8::try_from(-1i32)` is negative -> Err; `i8::try_from(-1i32)` fits -> Ok.
#[test]
fn try_from_signed_unsigned_boundaries() {
    let i8_overflow = r#"
        #[test]
        fn t_i8_overflow() {
            assert!(i8::try_from(200u16).is_err());
        }
    "#;
    let out = lift_file(&parse(i8_overflow), "coretests/num/i8_overflow.rs");
    if let Some(sat) = z3_verdict(&inv_json(&out.decls[0]), "t_i8_overflow") {
        assert!(sat, "200 > i8::MAX(127) -> is_err() == true -- must be SAT");
    }
    let u8_neg = r#"
        #[test]
        fn t_u8_neg() {
            assert!(u8::try_from(-1i32).is_err());
        }
    "#;
    let out = lift_file(&parse(u8_neg), "coretests/num/u8_neg.rs");
    if let Some(sat) = z3_verdict(&inv_json(&out.decls[0]), "t_u8_neg") {
        assert!(
            sat,
            "-1 < 0 -> u8::try_from is_err() == true -- must be SAT"
        );
    }
    // -1 fits i8 -> Ok; claiming is_err refutes.
    let i8_neg_ok = r#"
        #[test]
        fn t_i8_neg_ok_bad() {
            assert!(i8::try_from(-1i32).is_err());
        }
    "#;
    let out = lift_file(&parse(i8_neg_ok), "coretests/num/i8_neg_ok_bad.rs");
    if let Some(sat) = z3_verdict(&inv_json(&out.decls[0]), "t_i8_neg_ok_bad") {
        assert!(!sat, "-1 fits i8 -> is_err() is false -- must be UNSAT");
    }
}

// EXACT-OR-OPAQUE: a non-integer destination must not be owned by integer
// `try_from`; a runtime arg may be recognized as the `try_from` surface, but
// desugar must fall back to the opaque call rather than guessing Ok/Err.
#[test]
fn try_from_non_integer_and_runtime_decline() {
    // Non-integer destination: `char::try_from(..)` is not an integer try_from.
    let ch = r#"
        #[test]
        fn t_try_from_char() {
            assert!(char::try_from(65u32).is_ok());
        }
    "#;
    let out = lift_file(&parse(ch), "coretests/char/try_from_char.rs");
    assert!(
        !out.factory_audits
            .iter()
            .any(|a| a.selected == Some("try_from")),
        "a non-integer destination must NOT be folded by try_from: {:?}",
        out.factory_audits
    );
    // Runtime argument: not a literal -> lazy desugar falls back to the opaque call.
    let rt = r#"
        #[test]
        fn t_try_from_runtime() {
            let n = std::env::args().count() as u16;
            assert!(u8::try_from(n).is_err());
        }
    "#;
    let out = lift_file(&parse(rt), "coretests/num/try_from_runtime.rs");
    assert!(
        out.factory_audits
            .iter()
            .any(|a| a.selected == Some("try_from")),
        "the primitive try_from site should be owned lazily by try_from: {:?}",
        out.factory_audits
    );
    let dump = format!("{:?}", out.decls);
    assert!(
        dump.contains("call:u8::try_from") && !dump.contains("res:ok") && !dump.contains("res:err"),
        "runtime try_from must remain the opaque call fallback, not a fabricated Result: {dump}"
    );
}

#[test]
fn try_from_normal_return_support_is_well_sorted_and_bad_twin_refutes() {
    let good = r#"
        #[test]
        fn t_try_from_full_inv() {
            assert!(u8::try_from(255u16).unwrap() == 255);
        }
    "#;
    let out = lift_file(&parse(good), "coretests/num/tf_full_inv.rs");
    assert_eq!(
        out.assertions_lifted, 1,
        "try_from unwrap assertion must lift: {:?}",
        out.skip_reasons
    );
    let dump = format!("{:?}", out.decls);
    assert!(
        dump.contains("panic") && dump.contains("call:u8::try_from"),
        "normal-return support must use an opaque callsite subject, not the returned Result value: {dump}"
    );
    assert!(
        !dump.contains("panic\", args: [Ctor { name: \"res:ok\"")
            && !dump.contains("panic\", args: [Ctor { name: \"res:err\""),
        "panic predicate must never receive a Result ADT term: {dump}"
    );
    for (i, decl) in all_warranted_decls(&out).iter().enumerate() {
        if let Some(sat) = z3_verdict(&inv_json(decl), &format!("try_from_full_inv_good_{i}")) {
            assert!(
                sat,
                "every full warranted TryFrom invariant must be SAT and well-sorted"
            );
        }
    }

    let bad = r#"
        #[test]
        fn t_try_from_full_inv_bad() {
            assert!(u8::try_from(255u16).unwrap() == 254);
        }
    "#;
    let out = lift_file(&parse(bad), "coretests/num/tf_full_inv_bad.rs");
    assert_eq!(
        out.assertions_lifted, 1,
        "bad twin must still lift so the contradiction is checkable: {:?}",
        out.skip_reasons
    );
    if let Some(sat) = z3_verdict(
        &inv_json(single_warranted_decl(&out)),
        "try_from_full_inv_bad",
    ) {
        assert!(
            !sat,
            "bad twin try_from(255).unwrap() == 254 must be z3-UNSAT"
        );
    }
}

#[test]
fn option_returning_method_normal_return_support_uses_opaque_callsite() {
    let good = r#"
        #[test]
        fn t_checked_ilog_reflexive() {
            let got = 0u8.checked_ilog(4);
            assert_eq!(got, got);
        }
    "#;
    let out = lift_file(&parse(good), "coretests/num/checked_ilog_panic_sort.rs");
    assert_eq!(
        out.assertions_lifted, 1,
        "checked_ilog assertion should lift: {:?}",
        out.skip_reasons
    );
    let dump = format!("{:?}", out.decls);
    assert!(
        dump.contains("panic") && dump.contains("method:checked_ilog"),
        "normal-return support should mention the checked_ilog callsite: {dump}"
    );
    assert!(
        !dump.contains("panic\", args: [Ctor { name: \"opt:some\"")
            && !dump.contains("panic\", args: [Ctor { name: \"opt:none\""),
        "panic predicate must not receive the method's Option return value: {dump}"
    );
    for (i, decl) in all_warranted_decls(&out).iter().enumerate() {
        if let Some(sat) = z3_verdict(&inv_json(decl), &format!("checked_ilog_good_{i}")) {
            assert!(
                sat,
                "checked_ilog good invariant must be SAT and well-sorted"
            );
        }
    }

    let bad = r#"
        #[test]
        fn t_checked_ilog_anti_reflexive() {
            let got = 0u8.checked_ilog(4);
            assert_ne!(got, got);
        }
    "#;
    let out = lift_file(&parse(bad), "coretests/num/checked_ilog_panic_sort_bad.rs");
    assert_eq!(
        out.assertions_lifted, 1,
        "bad twin should lift so z3 can refute it: {:?}",
        out.skip_reasons
    );
    if let Some(sat) = z3_verdict(&inv_json(single_warranted_decl(&out)), "checked_ilog_bad") {
        assert!(!sat, "x != x over checked_ilog must be UNSAT");
    }
}

// ---- Lane 4: Range::size_hint decomposes to teethed component eqs ----

// `(0..100).size_hint()` is `(100, Some(100))`. Via the shared tuple_decomp hook,
// the tuple eq decomposes into per-component scalar eqs -- the count int and the
// `Some(n)` Option ADT -- each with REAL z3 teeth (not a teethless literal:Tuple).
#[test]
fn size_hint_decomposes_and_warrants() {
    let src = r#"
        #[test]
        fn t_size_hint() {
            assert_eq!((0..100).size_hint(), (100, Some(100)));
        }
    "#;
    let out = lift_file(&parse(src), "coretests/iter/range_size_hint.rs");
    assert_eq!(
        out.assertions_lifted, 1,
        "range size_hint must lift; skip: {:?}; audits: {:?}",
        out.skip_reasons, out.factory_audits
    );
    assert_eq!(out.assertions_refused, 0, "{:?}", out.skip_reasons);
    assert!(
        out.factory_audits
            .iter()
            .any(|a| a.selected.is_some_and(|s| s.contains("tuple_decomp"))),
        "size_hint tuple eq must decompose via tuple_decomp: {:?}",
        out.factory_audits
    );
    let dump = format!("{:?}", out.decls);
    assert!(
        dump.contains("Int(100)"),
        "the count component (100) must be a ground int: {dump}"
    );
    if let Some(sat) = z3_verdict(&inv_json(&out.decls[0]), "t_size_hint") {
        assert!(
            sat,
            "(0..100).size_hint() == (100, Some(100)) -- must be SAT"
        );
    }
}

// BAD TWINS / teeth: a wrong count, a wrong upper value, and a wrong upper
// VARIANT each refute (z3 UNSAT) -- one per component / ADT property.
#[test]
fn size_hint_wrong_components_are_unsat() {
    let count = r#"
        #[test]
        fn t_size_hint_count_bad() {
            assert_eq!((0..100).size_hint(), (99, Some(100)));
        }
    "#;
    let out = lift_file(&parse(count), "coretests/iter/sh_count_bad.rs");
    if let Some(sat) = z3_verdict(&inv_json(&out.decls[0]), "t_size_hint_count_bad") {
        assert!(!sat, "count is 100 != 99 -- must be UNSAT");
    }
    let upper = r#"
        #[test]
        fn t_size_hint_upper_bad() {
            assert_eq!((0..100).size_hint(), (100, Some(99)));
        }
    "#;
    let out = lift_file(&parse(upper), "coretests/iter/sh_upper_bad.rs");
    if let Some(sat) = z3_verdict(&inv_json(&out.decls[0]), "t_size_hint_upper_bad") {
        assert!(!sat, "upper is Some(100) != Some(99) -- must be UNSAT");
    }
    let variant = r#"
        #[test]
        fn t_size_hint_variant_bad() {
            assert_eq!((0..100).size_hint(), (100, None));
        }
    "#;
    let out = lift_file(&parse(variant), "coretests/iter/sh_variant_bad.rs");
    if let Some(sat) = z3_verdict(&inv_json(&out.decls[0]), "t_size_hint_variant_bad") {
        assert!(!sat, "upper is Some(100) != None -- must be UNSAT");
    }
}

// Semantics: negative endpoints and the empty/inclusive cases compute exactly.
#[test]
fn size_hint_negative_and_inclusive_semantics() {
    // (-10..-1) -> count 9.
    let neg = r#"
        #[test]
        fn t_sh_neg() {
            assert_eq!((-10..-1).size_hint(), (9, Some(9)));
        }
    "#;
    let out = lift_file(&parse(neg), "coretests/iter/sh_neg.rs");
    if let Some(sat) = z3_verdict(&inv_json(&out.decls[0]), "t_sh_neg") {
        assert!(sat, "(-10..-1) has 9 elements -- must be SAT");
    }
    // (-1..-10) is empty -> (0, Some(0)).
    let empty = r#"
        #[test]
        fn t_sh_empty() {
            assert_eq!((-1..-10).size_hint(), (0, Some(0)));
        }
    "#;
    let out = lift_file(&parse(empty), "coretests/iter/sh_empty.rs");
    if let Some(sat) = z3_verdict(&inv_json(&out.decls[0]), "t_sh_empty") {
        assert!(sat, "(-1..-10) is empty -- must be SAT");
    }
    // Inclusive (0..=4) -> count 5.
    let incl = r#"
        #[test]
        fn t_sh_incl() {
            assert_eq!((0..=4).size_hint(), (5, Some(5)));
        }
    "#;
    let out = lift_file(&parse(incl), "coretests/iter/sh_incl.rs");
    if let Some(sat) = z3_verdict(&inv_json(&out.decls[0]), "t_sh_incl") {
        assert!(sat, "(0..=4) has 5 elements -- must be SAT");
    }
    // Inclusive bad twin: (0..=4) is 5, not 6.
    let incl_bad = r#"
        #[test]
        fn t_sh_incl_bad() {
            assert_eq!((0..=4).size_hint(), (6, Some(6)));
        }
    "#;
    let out = lift_file(&parse(incl_bad), "coretests/iter/sh_incl_bad.rs");
    if let Some(sat) = z3_verdict(&inv_json(&out.decls[0]), "t_sh_incl_bad") {
        assert!(!sat, "(0..=4) has 5 != 6 elements -- must be UNSAT");
    }
}

// EXACT-OR-NONE: a runtime-bounded range size_hint is owned by the delayed tuple
// producer, but it must refuse at desugar time (the count is not text-determined)
// -- no guessed pair, no warranted scalar assertion.
#[test]
fn runtime_size_hint_declines_to_decompose() {
    let src = r#"
        #[test]
        fn t_sh_runtime() {
            let n = std::env::args().count();
            assert_eq!((0..n).size_hint(), (n, Some(n)));
        }
    "#;
    let out = lift_file(&parse(src), "coretests/iter/sh_runtime.rs");
    assert_eq!(out.assertions_lifted, 0, "{:?}", out.decls);
    assert!(
        out.skip_reasons
            .iter()
            .any(|reason| reason.contains("literal range bound is not text-determined")),
        "runtime-bounded size_hint must refuse with the runtime-bound reason: {:?}",
        out.skip_reasons
    );
    assert!(
        out.factory_audits
            .iter()
            .any(|a| a.selected == Some("size_hint_tuple_producer")
                && a.reason.as_deref().is_some_and(
                    |reason| reason.contains("literal range bound is not text-determined")
                )),
        "a runtime-bounded size_hint must be owned, then refused by the producer: {:?}",
        out.factory_audits
    );
}

