#[test]
fn mixed_supported_and_refinement_assertions_lift_supported_rows() {
    let src = r#"
struct Duration;

impl Duration {
    fn div_duration_f64(&self, _other: Duration) -> f64 { 2.0 }
}

#[test]
fn float_mixed_refinement_gap() {
    let d = Duration;
    assert_eq!(d.div_duration_f64(Duration), 2.0);
    assert!(d.div_duration_f64(Duration).is_nan());
    assert!(!d.div_duration_f64(Duration).is_nan());
}
"#;
    let out = lift_file(&parse(src), "tests/time.rs");
    assert_eq!(out.seen, 1);
    assert_eq!(out.lifted, 1, "warnings: {:?}", out.warnings);
    assert_eq!(
        out.warnings.len(),
        0,
        "width-known NaN refinements over method float results are liftable"
    );
    assert_warranted_decl_count(&out, 1);

    let decl = single_warranted_decl(&out);
    assert_eq!(
        decl.name,
        "method:div_duration_f64#euf#c:callresult_method_div_duration_f64_a2(v:tests/time.rs::float_mixed_refinement_gap::Duration,v:tests/time.rs::float_mixed_refinement_gap::Duration)::assertion"
    );
    let operands = inv_operands(decl);
    assert_eq!(operands.len(), 3);
    assert_real_call_eq_atom(&operands[0], "method:div_duration_f64", "2.0");
    assert_float_refinement_atom(&operands[1], "float.f64.is_nan", "method:div_duration_f64");
    match operands[2].as_ref() {
        Formula::Connective { kind, operands } if kind == "not" => {
            assert_eq!(operands.len(), 1);
            assert_float_refinement_atom(
                operands[0].as_ref(),
                "float.f64.is_nan",
                "method:div_duration_f64",
            );
        }
        other => panic!("expected negated float refinement atom, got {other:?}"),
    }

    let out = lift_one(
        r#"#[test]
fn nan_tuple_partial_ord() {
    assert!(!((1.0f64, 2.0f64) < (f64::NAN, 3.0)));
}"#,
    );
    assert_warranted_decls_not_refuted(&out, "nan_tuple_partial_ord");
    assert!(
        out.skip_reasons
            .iter()
            .any(|r| r.contains("NaN comparison") && r.contains("refused")),
        "NaN tuple partial order must be named-refused, not checked as ordinary \
         total order: {:?}",
        out.skip_reasons
    );

    let out = lift_one(
        r#"#[test]
fn nan_array_slice_equality() {
    let array3: [f32; 3] = [1.0, f32::NAN, 3.0];
    let slice3: &[f32] = &{ array3 };
    assert!(array3 != slice3);
}"#,
    );
    assert_warranted_decls_not_refuted(&out, "nan_array_slice_equality");
    assert!(
        out.skip_reasons
            .iter()
            .any(|r| r.contains("NaN comparison") && r.contains("refused")),
        "NaN array/slice equality must be named-refused, not checked as ordinary \
         equality: {:?}",
        out.skip_reasons
    );
}

