    // Vendor shape: rust-src library/coretests/tests/array.rs::iterator_last.
    let good = r#"
#[test]
fn iterator_last_literal_array() {
    assert_eq!(IntoIterator::into_iter([0]).last().unwrap(), 0);
}
"#;
    let out = lift_file(&parse(good), "tests/array.rs");
