#[test]
fn immutable_index_in_pointer_eq_predicate_stays_location_keyed() {
    // Vendor shape: rust-src library/coretests/tests/array.rs::array_from_ref.
    // The index expression is pure identity syntax here, but pointer equality is
    // only claimed at the test locus. Cross-proof pointer identity is not a
    // federated call-result key.
    let src = r#"
#[test]
fn array_from_ref() {
    const VALUE: &&str = &"Hello World!";
    const ARR: &[&str; 1] = core::array::from_ref(VALUE);
    assert!(core::ptr::eq(VALUE, &ARR[0]));
}
"#;
    let out = lift_file(&parse(src), "tests/array.rs");
    assert_eq!(out.seen, 1);
    assert_eq!(out.lifted, 1, "warnings: {:?}", out.warnings);
    assert!(
        out.warnings.is_empty(),
        "immutable index inside pointer equality should lift: {:?}",
        out.warnings
    );
    assert_warranted_decl_count(&out, 1);
    let decl = single_warranted_decl(&out);
    assert_eq!(decl.name, "tests/array.rs::array_from_ref");

    let operands = inv_operands(decl);
    assert_eq!(operands.len(), 1);
    match operands[0].as_ref() {
        Formula::Atomic { name, args } => {
            assert_eq!(name, "=");
            assert_eq!(args.len(), 2);
            match args[0].as_ref() {
                Term::Ctor { name, args } => {
                    assert_eq!(name, "call:core::ptr::eq");
                    assert_eq!(args.len(), 2);
                    match args[1].as_ref() {
                        Term::Ctor { name, args } => {
                            assert_eq!(name, "ref");
                            assert_eq!(args.len(), 1);
                            match args[0].as_ref() {
                                Term::Ctor { name, args } => {
                                    assert_eq!(name, "index");
                                    assert_eq!(args.len(), 2);
                                }
                                other => panic!("expected index term, got {other:?}"),
                            }
                        }
                        other => panic!("expected ref indexed argument, got {other:?}"),
                    }
                }
                other => panic!("expected ptr::eq call lhs, got {other:?}"),
            }
            assert_scalar_const(&args[1], ExpectedScalar::Bool(true));
        }
        other => panic!("expected pointer equality atom, got {other:?}"),
    }
}

#[test]
fn immutable_index_equality_grounds_to_element() {
    // An immutable (non-mut) literal container indexed by a const GROUNDS to the
    // concrete element (T's `[[1,2]][0][1]` thesis): `xs[0]` with `xs=[1,2,3]`
    // desugars straight to `1`, so the equality lifts as `1 == 1` -- NOT the
    // symbolic `index(xs,0)` ctor. Grounding is the soundness fix: an
    // uninterpreted `index(literal,const)` over-discharges (a bad-twin with the
    // wrong expected value would be falsely SAT).
    let src = r#"
#[test]
fn indexed_value() {
    let xs = [1, 2, 3];
    assert_eq!(xs[0], 1);
}
"#;
    let out = lift_file(&parse(src), "tests/index.rs");
    assert_eq!(out.seen, 1);
    assert_eq!(
        out.lifted, 1,
        "immutable index equality must lift: {:?}",
        out.warnings
    );
    let ops = inv_operands(&out.decls[0]);
    assert_eq!(ops.len(), 1);
    match ops[0].as_ref() {
        Formula::Atomic { name, args } => {
            assert_eq!(name, "=");
            assert_scalar_const(&args[0], ExpectedScalar::Int(1));
            assert_scalar_const(&args[1], ExpectedScalar::Int(1));
        }
        other => panic!("expected equality, got {other:?}"),
    }
}

