// NOTE: these three EUF-callsite-key tests use an OPAQUE-bodied `value() { opaque() }`
// (a call to a no-source fn) deliberately. A pure literal body (`{ 6 }`) would now be
// PEELED by term-position value-call inlining (capability #1) to the grounded literal
// `6`, eliminating the `call:value` EUF symbol these tests exist to exercise. The opaque
// body BAILS the peel (its body bottoms out in a no-source `call:opaque`), so `value()`
// stays the opaque `call:value` ctor under its EUF callsite key -- exactly the path here.
#[test]
fn call_result_comparison_assertions_use_fol_atoms_and_euf_key() {
    let src = r#"
fn value() -> i32 { opaque() }

#[test]
fn comparison_atoms() {
    assert!(value() > 3);
    assert!(value() <= 9);
    assert!(value() != 7);
}
"#;
    let out = lift_file(&parse(src), "tests/compare.rs");
    assert_eq!(out.seen, 1);
    assert_eq!(out.lifted, 1, "warnings: {:?}", out.warnings);
    assert_warranted_decl_count(&out, 1);

    let decl = single_warranted_decl(&out);
    assert_eq!(
        decl.name,
        "tests/compare.rs::comparison_atoms::value#euf#c:callresult_value_a0()::assertion"
    );
    let operands = inv_operands(decl);
    assert_eq!(operands.len(), 3);
    assert_int_call_cmp_atom(&operands[0], ">", "call:value", 3);
    assert_int_call_cmp_atom(&operands[1], "\u{2264}", "call:value", 9);
    assert_int_call_cmp_atom(&operands[2], "\u{2260}", "call:value", 7);
}

#[test]
fn same_callsite_connectives_lift_as_fol_connectives_under_euf_key() {
    let src = r#"
fn value() -> i32 { opaque() }

#[test]
fn connective_atoms() {
    assert!(value() > 3 && value() < 9);
    assert!(value() < 3 || value() > 5);
}
"#;
    let out = lift_file(&parse(src), "tests/compare.rs");
    assert_eq!(out.seen, 1);
    assert_eq!(out.lifted, 1, "warnings: {:?}", out.warnings);
    assert_warranted_decl_count(&out, 1);

    let decl = single_warranted_decl(&out);
    assert_eq!(
        decl.name,
        "tests/compare.rs::connective_atoms::value#euf#c:callresult_value_a0()::assertion"
    );
    let operands = inv_operands(decl);
    assert_eq!(operands.len(), 2);
    match operands[0].as_ref() {
        Formula::Connective { kind, operands } => {
            assert_eq!(kind, "and");
            assert_eq!(operands.len(), 2);
            assert_int_call_cmp_atom(&operands[0], ">", "call:value", 3);
            assert_int_call_cmp_atom(&operands[1], "<", "call:value", 9);
        }
        other => panic!("expected and connective, got {other:?}"),
    }
    match operands[1].as_ref() {
        Formula::Connective { kind, operands } => {
            assert_eq!(kind, "or");
            assert_eq!(operands.len(), 2);
            assert_int_call_cmp_atom(&operands[0], "<", "call:value", 3);
            assert_int_call_cmp_atom(&operands[1], ">", "call:value", 5);
        }
        other => panic!("expected or connective, got {other:?}"),
    }
}

