#[test]
fn macro_generated_module_run_calls_recurse_with_module_consts() {
    let src = r#"
#[test]
fn t() {
    macro_rules! suite {
        ( $( $fn:ident => [$a:expr, $nine:expr]; )* ) => {
            $(
                mod $fn {
                    const CHAR_A: bool = 'a'.$fn();
                    const CHAR_NINE: bool = '9'.$fn();

                    pub fn run() {
                        assert_eq!(CHAR_A, $a);
                        assert_eq!(CHAR_NINE, $nine);
                    }
                }
            )*

            $( $fn::run(); )*
        }
    }

    suite! {
        is_ascii_alphabetic => [true, false];
        is_ascii_digit => [false, true];
    }
}
"#;
    let out = lift_file(&parse(src), "tests/module_suite.rs");
    let scalar_claims: usize = out
        .assertion_facts
        .iter()
        .filter(|fact| fact.kind == AssertionFactKind::Warranted)
        .map(|fact| fact.claim_count)
        .sum();
    assert_eq!(
        scalar_claims, 4,
        "macro-generated module::run callsites should recurse through module consts: skips={:?} facts={:?} decls={:?}",
        out.skip_reasons,
        out.assertion_facts,
        out.decls
    );
    assert_eq!(
        out.assertion_facts
            .iter()
            .filter(|fact| {
                fact.kind == AssertionFactKind::Warranted
                    && fact.claim_count == 0
                    && fact.contract_name.contains("::run")
            })
            .count(),
        2,
        "module::run callsites should also emit warranted panic-free universes: {:?}",
        out.assertion_facts
    );
    assert!(
        out.skip_reasons
            .iter()
            .all(|reason| !reason.contains("support facts")),
        "module recursion must not stop at support-only macro accounting: {:?}",
        out.skip_reasons
    );
}

#[test]
fn dependency_macro_registry_learns_layered_value_assertion_shape() {
    let dep = r#"
macro_rules! ready_shape {
    ($e:expr) => {{
        use core::task::Poll;
        match $e {
            Poll::Ready(v) => v,
            Poll::Pending => panic!("pending"),
        }
    }};
}

macro_rules! ok_shape {
    ($e:expr) => {{
        match $e {
            Ok(v) => v,
            Err(e) => panic!("not ok: {:?}", e),
        }
    }};
}

macro_rules! ready_ok_shape {
    ($e:expr) => {{
        use vendor_asserts::{ready_shape, ok_shape};
        let val = ready_shape!($e);
        ok_shape!(val)
    }};
}
"#;
    let mut macros = MacroRegistry::new();
    macros.scan_source(dep);
    let consts = ConstSourceRegistry::new();
    let src = r#"
#[test]
fn t() {
    assert_eq!(ready_ok_shape!(Poll::Ready(Ok::<i32, i32>(3))), 3);
}
"#;
    let out = lift_file_with_source_imports(
        &parse(src),
        "tests/vendor_layered_value_shape.rs",
        &LiftOptions::default(),
        &macros,
        &consts,
    );

    assert_eq!(
        out.assertions_lifted, 1,
        "dependency-provided layered value assertion shape should lift without naming the vendor: skipped={:?} facts={:?} decls={:?}",
        out.skip_reasons,
        out.assertion_facts,
        out.decls
    );
    let decl = single_warranted_decl(&out);
    let dump = format!("{:?}", decl.inv);
    assert!(
        dump.contains("3"),
        "the value-producing macro chain should keep the literal payload visible: {dump}"
    );
    assert!(
        out.skip_reasons
            .iter()
            .all(|r| !r.contains("unsupported assertion macro") && !r.contains("unsupported term")),
        "the dependency macro must be learned by source shape, not macro name or opaque block fallback: {:?}",
        out.skip_reasons
    );
}

