// ── TermBreadth: float casts + unsafe-block transparency + try/async refuse ──

// (A) FLOAT CAST -- `x as f32` lifts to the OPAQUE EUF ctor `cast:f32(x)`, the same
// standard as the integer/char casts. The `num/mod.rs::test_f32f64` round-trip rows
// (`assert_eq!(max as f32, f32::MAX)`, ...) fell out at the cast fallthrough; now
// the LHS lifts and the row pins as a structural equality.
#[test]
fn float_cast_lifts_as_opaque_euf_ctor() {
    let src = r#"
#[test]
fn cast_f32() {
    let x: f64 = 1.0;
    assert_eq!(x as f32, 1.0f32);
}
"#;
    let out = lift_file(&parse(src), "tests/num.rs");
    assert_eq!(out.seen, 1);
    assert_eq!(
        out.lifted, 1,
        "float-cast assert must lift: {:?}",
        out.warnings
    );
    let operands = inv_operands(&out.decls[0]);
    assert_eq!(operands.len(), 1);
    match operands[0].as_ref() {
        Formula::Atomic { name, args } => {
            assert_eq!(name, "=");
            match args[0].as_ref() {
                Term::Ctor { name, args } => {
                    assert_eq!(name, "cast:f32", "LHS is the opaque float-cast ctor");
                    assert_eq!(args.len(), 1);
                    assert!(
                        matches!(args[0].as_ref(), Term::Var { .. } | Term::Const { .. }),
                        "cast operand is the canonical receiver value, got {:?}",
                        args[0]
                    );
                }
                other => panic!("expected cast:f32 lhs, got {other:?}"),
            }
        }
        other => panic!("expected cast equality atom, got {other:?}"),
    }
}

// (A) ADVERSARIAL bad-twin: the SAME `cast:f32(x)` term cannot equal two distinct
// pinned floats. A test that asserts `x as f32 == 1.0` AND `x as f32 == 2.0` lifts a
// conjunction that is z3-UNSAT -- the structural equality has teeth, a wrong-expected
// twin is REFUTED (it is not opaqued into a free pass).
#[test]
fn float_cast_contradictory_expected_is_unsat() {
    let src = r#"
#[test]
fn cast_f32_contradiction() {
    let x: f64 = 1.0;
    assert_eq!(x as f32, 1.0f32);
    assert_eq!(x as f32, 2.0f32);
}
"#;
    let out = lift_file(&parse(src), "tests/num.rs");
    assert_eq!(
        out.lifted, 1,
        "both casted asserts lift into one row: {:?}",
        out.warnings
    );
    // Two operands over the SAME cast term, pinned to two different reals.
    assert_eq!(inv_operands(&out.decls[0]).len(), 2);
    if let Some(sat) = z3_verdict(&inv_json(&out.decls[0]), "float_cast_contra") {
        assert!(!sat, "cast:f32(x)==1.0 AND ==2.0 must be UNSAT (the teeth)");
    }
}

// (A) DISCRIMINATION: a pointer-target cast still REFUSES (the float widening did not
// loosen raw-pointer boundary accounting). Guards against over-widening
// `scalar_cast_type_key`.
#[test]
fn float_cast_does_not_loosen_pointer_target_refusal() {
    let src = r#"
#[test]
fn ptr_cast() {
    assert_eq!(source() as *const f32, source());
}
"#;
    let out = lift_file(&parse(src), "tests/num.rs");
    assert!(
        warranted_decls(&out).is_empty(),
        "pointer-target cast must not emit warranted facts: {:?}",
        out.assertion_facts
    );
    assert!(
        out.skip_reasons.iter().any(|r| {
            r.contains("effectful / raw-pointer / mutable-reference term")
                && r.contains("raw pointer cast")
        }),
        "pointer-target cast must be refused as raw-pointer boundary: {:?}",
        out.skip_reasons
    );
}

// (B) UNSAFE-BLOCK TRANSPARENCY -- a single-tail `unsafe { <expr> }` in term position
// lifts to the SAME term as the bare `<expr>`: the `unsafe` wrapper is congruent. The
// `result.rs`/`cell.rs`/`mem.rs` rows (`assert_eq!(unsafe { ok.unwrap_unchecked() },
// 100)`, ...) fell out at the wrapper; now they lift via the inner method-call EUF.
#[test]
fn unsafe_block_is_value_transparent_congruent_to_bare_expr() {
    let wrapped = r#"
#[test]
fn t() {
    assert_eq!(unsafe { ok.unwrap_unchecked() }, 100);
}
"#;
    let bare = r#"
#[test]
fn t() {
    assert_eq!(ok.unwrap_unchecked(), 100);
}
"#;
    let ow = lift_file(&parse(wrapped), "tests/result.rs");
    let ob = lift_file(&parse(bare), "tests/result.rs");
    assert_eq!(
        ow.lifted, 1,
        "unsafe-wrapped assert must lift: {:?}",
        ow.warnings
    );
    assert_eq!(ob.lifted, 1, "bare assert must lift: {:?}", ob.warnings);
    // CONGRUENCE: the unsafe wrapper introduces no new shape -- the two invs are
    // byte-identical (same canonical FOL).
    assert_eq!(
        format!("{:?}", inv_operands(&ow.decls[0])),
        format!("{:?}", inv_operands(&ob.decls[0])),
        "unsafe {{ e }} must lift to the same term as bare e (transparency)"
    );
}

// (B) ADVERSARIAL bad-twin: the transparent unsafe row still has teeth -- the same
// inner value cannot equal two distinct pins, so a wrong-expected twin is UNSAT.
// (B) STRUCTURAL discrimination: only the WRAPPER is transparent. A temporally-unstable
// inner read (`&mut *cell.get()` -- `&mut` of a deref, not an immutable value) still
// BAILS through the ordinary operand path. No fake-dig: the unsafe wrapper does not
// launder a mutable-raw deref into a discharge.
#[test]
fn unsafe_block_mutable_raw_deref_still_bails() {
    let src = r#"
#[test]
fn t() {
    assert_eq!(unsafe { &mut *cell.get() }, comp);
}
"#;
    let out = lift_file(&parse(src), "tests/cell.rs");
    assert_eq!(
        out.lifted, 0,
        "mutable-raw deref under unsafe must NOT lift"
    );
    assert!(
        out.warnings
            .iter()
            .any(|w| w.reason.contains("unsupported term")),
        "the inner `&mut *p` must stay residual (only the wrapper is transparent): {:?}",
        out.warnings
    );
}

// (C) TRY/ASYNC BLOCK -> TERMINAL refuse. `assert!(Option::is_none(&try { join!(...) }))`
// (future.rs) is effectful control-flow -- a `try` block / `async` block / `?` is not a
// timeless point-wise value. It is a NAMED refusal whose disposition is TERMINAL
// (Refused), never Unclassified work.
#[test]
fn try_async_block_assert_is_terminal_refusal() {
    let src = r#"
#[test]
fn join_try() {
    assert!(Option::is_none(&try { join!(maybe_fut?, async { unreachable!() }) }));
}
"#;
    let out = lift_file(&parse(src), "tests/future.rs");
    assert_eq!(out.assertions_lifted, 0, "try-block assert must not lift");
    let reason = out
        .skip_reasons
        .iter()
        .find(|r| r.contains("effectful control-flow block"))
        .unwrap_or_else(|| {
            panic!(
                "expected an effectful-control-flow refusal, got {:?}",
                out.skip_reasons
            )
        });
    assert_eq!(
        sugar_lift_rust_tests::refusal_disposition(reason),
        sugar_lift_rust_tests::Disposition::Refused,
        "try/async control-flow block must classify TERMINAL refused, not unclassified work"
    );
}

// ── Statement-position qualified continue paths (value NOT in scope) ─────────
//
// The statement-position assert buckets split TWO ways. The value-NOT-in-scope half
// (the asserted value flows through a runtime continuation: a future `.await`, an
// assertion-bearing async future handed to a non-axiomatic driver, or opaque
// compile-time reflection) is a SOUND
// TERMINAL refusal naming that qualified continue path -- the SAME class as the
// existing `bin-2` "runtime data, not constructed from source literals" terminals.
// The discrimination guardrail (BOTH directions) is what keeps it from being a
// position-driven fake-refuse: a statement carrying a CONSTRUCTED literal value
// (a match over a literal scrutinee, a plain block over literals) is NOT
// terminalized -- it DIGS.

/// (refuse) An `assert_eq!(x, ..)` where `x = join!(..).await` inside a free-fn
/// `block_on(async {..})` is inside an async future handed to a non-axiomatic
/// driver. It must classify TERMINAL refused at the handoff boundary, NOT
/// discharge (recursing would FAKE-DIG `x == 0` as a literal, ignoring the runtime
/// await and the driver contract).
#[test]
fn await_in_block_on_is_terminal_refusal() {
    let src = r#"
#[test]
fn test_join() {
    block_on(async move {
        let x = join!(async { 0 }).await;
        assert_eq!(x, 0);
        let x = join!(async { 0 }, async { 1 }).await;
        assert_eq!(x, (0, 1));
    });
}
"#;
    let out = lift_file(&parse(src), "tests/future.rs");
    assert_eq!(
        out.assertions_lifted, 0,
        "await-bound asserts must NOT discharge (fake-dig risk): {:?}",
        out.warnings
    );
    let reason = out
        .skip_reasons
        .iter()
        .find(|r| r.contains("future handoff boundary"))
        .unwrap_or_else(|| {
            panic!(
                "expected a future-handoff refusal, got {:?}",
                out.skip_reasons
            )
        });
    assert_eq!(
        sugar_lift_rust_tests::refusal_disposition(reason),
        sugar_lift_rust_tests::Disposition::Refused,
        "free-fn block_on(async) future handoff must classify TERMINAL refused"
    );
}

/// (refuse) An `assert_eq!(b.field, ..)` read out of a `match Type::of::<T>().kind`
/// arm binder reads compile-time REFLECTION over runtime type identity (`TypeId`) --
/// not a value constructed from source literals (value NOT in scope). It must classify
/// TERMINAL refused over the named reflection scrutinee.
#[test]
fn reflection_match_body_is_terminal_refusal() {
    let src = r#"
#[test]
fn test_arrays() {
    match const { Type::of::<[u16; 4]>() }.kind {
        TypeKind::Array(array) => {
            assert_eq!(array.element_ty, TypeId::of::<u16>());
            assert_eq!(array.len, 4);
        }
        _ => unreachable!(),
    }
}
"#;
    let out = lift_file(&parse(src), "tests/mem/type_info.rs");
    let reason = out
        .skip_reasons
        .iter()
        .find(|r| r.contains("opaque compile-time reflection"))
        .unwrap_or_else(|| {
            panic!(
                "expected an opaque-reflection refusal, got {:?}",
                out.skip_reasons
            )
        });
    assert_eq!(
        sugar_lift_rust_tests::refusal_disposition(reason),
        sugar_lift_rust_tests::Disposition::Refused,
        "reflection-match body asserts must classify TERMINAL refused, not unclassified"
    );
    // Both body asserts are accounted as reflection (none left unenumerated).
    let refl = out
        .skip_reasons
        .iter()
        .filter(|r| r.contains("opaque compile-time reflection"))
        .count();
    assert_eq!(
        refl, 2,
        "both reflection body asserts refused: {:?}",
        out.skip_reasons
    );
    assert!(
        !out.skip_reasons
            .iter()
            .any(|r| r.contains("unenumerated statement position")),
        "no reflection body assert should fall to the unenumerated safety net: {:?}",
        out.skip_reasons
    );
}

/// (boundary/guardrail) A `match` over a CONSTRUCTED LITERAL scrutinee is NOT
/// reflection -- the value IS in scope. It must NOT be reflection-terminalized; it
/// digs (or stays unclassified), proving the refusal is qualification-driven (the
/// reflection scrutinee), not match-position-driven.
#[test]
fn literal_scrutinee_match_is_not_reflection_refused() {
    let src = r#"
#[test]
fn t() {
    let x = 3;
    match x {
        3 => assert_eq!(x, 3),
        _ => unreachable!(),
    }
}
"#;
    let out = lift_file(&parse(src), "tests/lit_match.rs");
    assert!(
        !out.skip_reasons
            .iter()
            .any(|r| r.contains("opaque compile-time reflection")),
        "a literal-scrutinee match must NEVER be reflection-refused: {:?}",
        out.skip_reasons
    );
    assert_eq!(
        out.lifted, 1,
        "the literal match digs (panic-locus variant pin): {:?}",
        out.warnings
    );
}

/// (boundary/guardrail) A plain unconditional block over LITERALS carries an
/// in-scope value -- it must DIG, never be control-flow / await terminalized.
#[test]
fn literal_block_is_not_control_flow_refused() {
    let src = r#"
#[test]
fn t() {
    {
        let a = 5;
        assert_eq!(a, 5);
    }
}
"#;
    let out = lift_file(&parse(src), "tests/lit_block.rs");
    assert!(
        !out.skip_reasons
            .iter()
            .any(|r| r.contains("effectful control-flow block")
                || r.contains("opaque compile-time reflection")),
        "a literal block must NEVER be statement-position terminalized: {:?}",
        out.skip_reasons
    );
    assert_eq!(out.lifted, 1, "the literal block digs: {:?}", out.warnings);
    assert_eq!(
        out.assertions_lifted, 1,
        "the in-scope literal assert lifts"
    );
}

// ── DIG WAVE: versioned-cursor / bin-1 body-lift over LITERAL domains ─────────
//
// A `<lit-array>.iter().<adaptor>().fold(<init>, |acc, &x| { assert_eq!(x, ys[acc]); .. })`
// over LITERAL arrays is the finite conjunction of the per-step claims with the
// accumulator threaded to a concrete cursor position. THE LAW: the value at step k
// IS in scope -- the element is the literal `xs[..]` walked by the adaptor, and the
// indexed read `ys[acc]` (acc a literal position) resolves to the literal element.
// The fold INIT (`ys.len()` / `xs.len() - 1`) over a literal array is itself a
// literal cursor extent. EXACT-OR-BAIL: a runtime-indexed array or an un-nameable
// cursor stays unclassified, never fake-dug.

/// Collect every `(lhs, rhs)` int pair from the `=` atoms of a decl's flattened inv
/// conjunction. Both sides must be int consts (a fully-dug point-wise claim).
fn dug_eq_int_pairs(decl: &sugar_ir_symbolic::ContractDecl) -> Vec<(i128, i128)> {
    fn walk(f: &Formula, out: &mut Vec<(i128, i128)>) {
        match f {
            Formula::Atomic { name, args } if name == "=" && args.len() == 2 => {
                if let (
                    Term::Const {
                        value: ConstValue::Int(a),
                        ..
                    },
                    Term::Const {
                        value: ConstValue::Int(b),
                        ..
                    },
                ) = (args[0].as_ref(), args[1].as_ref())
                {
                    out.push((*a, *b));
                }
            }
            Formula::Connective { operands, .. } => {
                for op in operands {
                    walk(op, out);
                }
            }
            _ => {}
        }
    }
    let mut out = Vec::new();
    if let Some(inv) = decl.inv.as_deref() {
        walk(inv, &mut out);
    }
    out
}

/// The ctor-NAME pairs of every `=` atom whose BOTH operands are `Term::Ctor`
/// (e.g. `=(opt:some(1), opt:some(1))` -> `("opt:some","opt:some")`). Used to
/// assert the monadic `Option`/`Result` constructors GROUND to their reserved
/// ADT-backed names (not the federated `call:eq:Some` EUF, which would be a
/// `=(call:eq:Some(..), true)` shape with a Bool-const operand, not two ctors).
fn dug_eq_ctor_name_pairs(decl: &sugar_ir_symbolic::ContractDecl) -> Vec<(String, String)> {
    fn ctor_name(t: &Term) -> Option<String> {
        match t {
            Term::Ctor { name, .. } => Some(name.clone()),
            _ => None,
        }
    }
    fn walk(f: &Formula, out: &mut Vec<(String, String)>) {
        match f {
            Formula::Atomic { name, args } if name == "=" && args.len() == 2 => {
                if let (Some(a), Some(b)) =
                    (ctor_name(args[0].as_ref()), ctor_name(args[1].as_ref()))
                {
                    out.push((a, b));
                }
            }
            Formula::Connective { operands, .. } => {
                for op in operands {
                    walk(op, out);
                }
            }
            _ => {}
        }
    }
    let mut out = Vec::new();
    if let Some(inv) = decl.inv.as_deref() {
        walk(inv, &mut out);
    }
    out
}

/// True iff any atom anywhere in the decl names a ctor whose name CONTAINS
/// `needle` (e.g. `call:eq:Some`, `method:next`, `opt:some`). Walks both the
/// atom heads and every nested ctor operand.
fn decl_mentions_ctor(decl: &sugar_ir_symbolic::ContractDecl, needle: &str) -> bool {
    fn term_has(t: &Term, needle: &str) -> bool {
        match t {
            Term::Ctor { name, args } => {
                name.contains(needle) || args.iter().any(|a| term_has(a, needle))
            }
            _ => false,
        }
    }
    fn walk(f: &Formula, needle: &str) -> bool {
        match f {
            Formula::Atomic { name, args } => {
                name.contains(needle) || args.iter().any(|a| term_has(a, needle))
            }
            Formula::Connective { operands, .. } => operands.iter().any(|op| walk(op, needle)),
            Formula::Quantifier { body, .. } | Formula::Choice { body, .. } => walk(body, needle),
        }
    }
    decl.inv.as_deref().is_some_and(|inv| walk(inv, needle))
}

// ── MONADIC Option/Result constructors -- the structural-equality teeth ──────
//
// `Some(x)`/`Ok(x)`/`Err(x)`/`None` are CONSTRUCTORS OVER LITERALS -- sugar, the
// same family as the `array_term`/`tuple_term`/`struct_term` aggregates. They
// GROUND to the reserved `opt:some`/`opt:none`/`res:ok`/`res:err` ctor (NOT the
// federated, teeth-less `call:eq:Some` EUF), and the IR->SMT compiler declares
// `Option`/`Result` as ALGEBRAIC DATATYPES, so z3 enforces constructor
// injectivity (`Some a = Some b <=> a = b`) + distinctness (`Some _ != None`,
// `Ok _ != Err _`). The make-or-break HARD GATE: a bad twin goes z3-UNSAT.
// (`MonadicSugar`, `src/sugar/monadic.rs`; the ADT, `sugar-ir-compiler-smt-lib`.)

/// Lift a single `assert_eq!(<lhs>, <rhs>)` over no-receiver constants and
/// return the first decl. Used by the monadic teeth tests, which compare two
/// written constructor literals (no runtime receiver).
fn lift_eq_decl(lhs: &str, rhs: &str, file: &str) -> sugar_ir_symbolic::ContractDecl {
    let src = format!("#[test]\nfn t() {{ assert_eq!({lhs}, {rhs}); }}\n");
    let out = lift_file(&parse(&src), file);
    out.decls
        .into_iter()
        .next()
        .expect("the monadic equality must lift to a consistency contract")
}

#[test]
fn monadic_some_equal_is_sat_and_bad_twin_is_unsat() {
    // `Some(1) == Some(1)` is consistent (SAT); the bad twin `Some(1) == Some(2)`
    // is z3-UNSAT (constructor injectivity -- the teeth).
    let good = lift_eq_decl("Some(1)", "Some(1)", "tests/monadic_some_good.rs");
    assert_eq!(
        dug_eq_ctor_name_pairs(&good),
        vec![("opt:some".to_string(), "opt:some".to_string())],
        "Some(1)==Some(1) must ground to two opt:some ctors (NOT the federated call:eq:Some)"
    );
    assert!(
        !decl_mentions_ctor(&good, "call:eq:Some") && !decl_mentions_ctor(&good, "call:Some"),
        "no opaque federated/call ctor may survive: {:?}",
        good.inv
    );
    if let Some(sat) = z3_verdict(&inv_json(&good), "monadic_some_good") {
        assert!(sat, "Some(1)==Some(1) must be SAT");
    }

    let bad = lift_eq_decl("Some(1)", "Some(2)", "tests/monadic_some_bad.rs");
    if let Some(sat) = z3_verdict(&inv_json(&bad), "monadic_some_bad") {
        assert!(
            !sat,
            "the bad twin Some(1)==Some(2) must be z3-UNSAT (injectivity teeth)"
        );
    }
}

#[test]
fn monadic_some_vs_none_is_unsat() {
    // `Some(1) == None` is z3-UNSAT (constructor distinctness -- the teeth).
    let decl = lift_eq_decl("Some(1)", "None", "tests/monadic_some_none.rs");
    let pairs = dug_eq_ctor_name_pairs(&decl);
    assert_eq!(
        pairs,
        vec![("opt:some".to_string(), "opt:none".to_string())],
        "Some(1)==None must ground to opt:some vs opt:none ctors: {:?}",
        decl.inv
    );
    if let Some(sat) = z3_verdict(&inv_json(&decl), "monadic_some_none") {
        assert!(!sat, "Some(1)==None must be z3-UNSAT (distinctness teeth)");
    }
}

#[test]
fn monadic_result_ok_equal_sat_bad_twin_and_cross_variant_unsat() {
    // `Ok(1)==Ok(1)` SAT; `Ok(1)==Ok(2)` UNSAT (injectivity); `Ok(1)==Err(1)`
    // UNSAT (cross-variant distinctness).
    let good = lift_eq_decl("Ok(1)", "Ok(1)", "tests/monadic_ok_good.rs");
    assert_eq!(
        dug_eq_ctor_name_pairs(&good),
        vec![("res:ok".to_string(), "res:ok".to_string())],
        "Ok(1)==Ok(1) must ground to two res:ok ctors"
    );
    if let Some(sat) = z3_verdict(&inv_json(&good), "monadic_ok_good") {
        assert!(sat, "Ok(1)==Ok(1) must be SAT");
    }

    let bad = lift_eq_decl("Ok(1)", "Ok(2)", "tests/monadic_ok_bad.rs");
    if let Some(sat) = z3_verdict(&inv_json(&bad), "monadic_ok_bad") {
        assert!(!sat, "Ok(1)==Ok(2) must be z3-UNSAT (injectivity)");
    }

    let cross = lift_eq_decl("Ok(1)", "Err(1)", "tests/monadic_ok_err.rs");
    assert_eq!(
        dug_eq_ctor_name_pairs(&cross),
        vec![("res:ok".to_string(), "res:err".to_string())],
        "Ok(1)==Err(1) must ground to res:ok vs res:err ctors"
    );
    if let Some(sat) = z3_verdict(&inv_json(&cross), "monadic_ok_err") {
        assert!(
            !sat,
            "Ok(1)==Err(1) must be z3-UNSAT (cross-variant distinctness)"
        );
    }
}

#[test]
fn iter_next_over_literal_array_grounds_to_some_first_element() {
    // THE MARQUEE: `assert_eq!([1,2,3].iter().next(), Some(&1))` is sugar all the
    // way to literals. The LHS `.next()` grounds (positional unroll over the
    // literal Seq) to `opt:some(1)`; the RHS `Some(&1)` grounds (the `&` stripped)
    // to `opt:some(1)`. The atom is `=(opt:some(1), opt:some(1))` -- an int-level
    // pinned equality, NOT an opaque `method:next` / `call:eq:Some` var.
    let good_out = lift_file(
        &parse("#[test]\nfn t() { assert_eq!([1, 2, 3].iter().next(), Some(&1)); }\n"),
        "tests/iter_next_good.rs",
    );
    assert_eq!(
        good_out.skip_reasons,
        Vec::<String>::new(),
        "the literal-domain `.next()` must dig, not refuse: {:?}",
        good_out.skip_reasons
    );
    let good = &good_out.decls[0];
    assert_eq!(
        dug_eq_ctor_name_pairs(good),
        vec![("opt:some".to_string(), "opt:some".to_string())],
        "`.next()` and `Some(&1)` must BOTH ground to opt:some (no opaque var): {:?}",
        good.inv
    );
    assert!(
        !decl_mentions_ctor(good, "method:next") && !decl_mentions_ctor(good, "call:eq:Some"),
        "no opaque method:next / call:eq:Some may survive: {:?}",
        good.inv
    );
    if let Some(sat) = z3_verdict(&inv_json(good), "iter_next_good") {
        assert!(sat, "`Some(1) == Some(1)` (the grounded next) must be SAT");
    }

    // BAD TWIN: `Some(&2)` -> `opt:some(2)` -> `=(opt:some(1), opt:some(2))` ->
    // z3-UNSAT (the real teeth; the old opaque form left it SAT).
    let bad = lift_eq_decl(
        "[1, 2, 3].iter().next()",
        "Some(&2)",
        "tests/iter_next_bad.rs",
    );
    if let Some(sat) = z3_verdict(&inv_json(&bad), "iter_next_bad") {
        assert!(
            !sat,
            "the bad twin `.next() == Some(&2)` must be z3-UNSAT (injectivity teeth)"
        );
    }
}

#[test]
fn iter_nth_and_last_over_literal_array_ground_with_teeth() {
    // `.nth(k)` -> `Some(elem[k])`; `.last()` -> `Some(elem[len-1])`. Past the end
    // -> `None`. Each grounds with bad-twin teeth.
    // `.nth(1)` of [10,20,30] is 20.
    let nth = lift_eq_decl(
        "[10, 20, 30].iter().nth(1)",
        "Some(&20)",
        "tests/iter_nth_good.rs",
    );
    assert_eq!(
        dug_eq_ctor_name_pairs(&nth),
        vec![("opt:some".to_string(), "opt:some".to_string())],
        "`.nth(1)` must ground to opt:some(20): {:?}",
        nth.inv
    );
    if let Some(sat) = z3_verdict(&inv_json(&nth), "iter_nth_good") {
        assert!(sat, "`.nth(1) == Some(20)` must be SAT");
    }
    let nth_bad = lift_eq_decl(
        "[10, 20, 30].iter().nth(1)",
        "Some(&21)",
        "tests/iter_nth_bad.rs",
    );
    if let Some(sat) = z3_verdict(&inv_json(&nth_bad), "iter_nth_bad") {
        assert!(!sat, "`.nth(1) == Some(21)` must be z3-UNSAT");
    }

    // `.last()` of [10,20,30] is 30.
    let last = lift_eq_decl(
        "[10, 20, 30].iter().last()",
        "Some(&30)",
        "tests/iter_last_good.rs",
    );
    assert_eq!(
        dug_eq_ctor_name_pairs(&last),
        vec![("opt:some".to_string(), "opt:some".to_string())],
        "`.last()` must ground to opt:some(30): {:?}",
        last.inv
    );
    if let Some(sat) = z3_verdict(&inv_json(&last), "iter_last_good") {
        assert!(sat, "`.last() == Some(30)` must be SAT");
    }

    // `.nth(9)` past the end -> `None`. Grounds to opt:none; `== None` is SAT,
    // `== Some(&1)` is z3-UNSAT (distinctness).
    let past = lift_eq_decl(
        "[10, 20, 30].iter().nth(9)",
        "None",
        "tests/iter_nth_past.rs",
    );
    assert_eq!(
        dug_eq_ctor_name_pairs(&past),
        vec![("opt:none".to_string(), "opt:none".to_string())],
        "`.nth(9)` past the end must ground to opt:none: {:?}",
        past.inv
    );
    if let Some(sat) = z3_verdict(&inv_json(&past), "iter_nth_past") {
        assert!(sat, "`.nth(9) == None` (both opt:none) must be SAT");
    }
    let past_bad = lift_eq_decl(
        "[10, 20, 30].iter().nth(9)",
        "Some(&1)",
        "tests/iter_nth_past_bad.rs",
    );
    if let Some(sat) = z3_verdict(&inv_json(&past_bad), "iter_nth_past_bad") {
        assert!(!sat, "`.nth(9) == Some(1)` must be z3-UNSAT (None != Some)");
    }
}

