    let out = lift_one(
        r#"#[test] fn t() { let f = &|acc, x| i32::checked_add(2 * acc, x);
        assert_eq!((0..10).map(|x| x + 3).try_fold(7, f), (3..13).try_fold(8, f)); }"#,
    );
