// ── STRUCTURAL: a RUNTIME (mutable-iterator) try_fold must NOT be grounded ─────

#[test]
fn runtime_iterator_try_fold_is_not_grounded() {
    // SOUNDNESS guardrail: `iter.try_fold(0, i8::checked_add)` over a `let mut iter`
    // is RUNTIME data -- the evaluator MUST bail, so the row keeps its existing
    // (non-grounded) classification. It must NEVER fabricate a `Some(n)` for an
    // advanced iterator. Asserting the WHOLE `test_map_try_folds` fn: the 2 closed
    // rows discharge, the runtime rows do not (they are refused / opaque, never a
    // fabricated grounded literal).
    let out = lift_one(
        r#"#[test]
fn test_map_try_folds() {
    let f = &|acc, x| i32::checked_add(2 * acc, x);
    assert_eq!((0..10).map(|x| x + 3).try_fold(7, f), (3..13).try_fold(7, f));
    assert_eq!((0..10).map(|x| x + 3).try_rfold(7, f), (3..13).try_rfold(7, f));

    let mut iter = (0..40).map(|x| x + 10);
    assert_eq!(iter.try_fold(0, i8::checked_add), None);
    assert_eq!(iter.next(), Some(20));
    assert_eq!(iter.try_rfold(0, i8::checked_add), None);
    assert_eq!(iter.next_back(), Some(46));
}"#,
    );
    // The closed rows (6,7) discharge to grounded `opt:some(_)==opt:some(_)`; the
    // runtime rows (10,12) keep their OPAQUE `method:try_fold` term, paired with the
    // REAL asserted `None` (`eq(method:try_fold[..], opt:none)`) -- never a FABRICATED
    // `Some(n)`. With `MonadicSugar` the equality is now a FLAT structural `=` atom
    // (not the old federated `call:eq:Some|None[..] == true` wrapper). The
    // fake-discharge we forbid is a single ATOM that pairs an opaque
    // `method:try_fold`/`method:try_rfold` ctor with a grounded `opt:some(<int>)`
    // (then z3 could pick the opaque term = that Some, a vacuous pass). Walk EACH atom
    // and assert no such pairing. (Two distinct atoms in the coalesced decl -- one
    // grounded row, one opaque runtime row -- is FINE; the guardrail is per-atom.)
    let mut saw_opaque_runtime = false;
    let mut saw_grounded = false;
    for d in &out.decls {
        for op in inv_operands(d) {
            let Formula::Atomic { name, args } = op.as_ref() else {
                continue;
            };
            if name != "=" || args.len() != 2 {
                continue;
            }
            // The two operands of the flat structural equality.
            let names: Vec<String> = args
                .iter()
                .map(|t| match t.as_ref() {
                    Term::Ctor { name, .. } => name.clone(),
                    _ => String::new(),
                })
                .collect();
            let has_opaque = names
                .iter()
                .any(|n| n == "method:try_fold" || n == "method:try_rfold");
            // A fabricated grounded `opt:some(<int>)` operand.
            let has_grounded_some = args.iter().any(|t| {
                matches!(t.as_ref(), Term::Ctor { name, args }
                    if name == "opt:some"
                        && matches!(args.first().map(|a| a.as_ref()),
                                    Some(Term::Const { value: ConstValue::Int(_), .. })))
            });
            assert!(
                !(has_opaque && has_grounded_some),
                "an opaque runtime try_fold paired with a fabricated grounded opt:some(_) \
                 in ONE atom is a vacuous fake-discharge: {names:?}"
            );
            if has_opaque {
                saw_opaque_runtime = true;
            }
            if names.iter().filter(|n| *n == "opt:some").count() == 2 {
                saw_grounded = true;
            }
        }
    }
    assert!(
        saw_grounded,
        "the 2 closed rows must ground to opt:some(_)==opt:some(_)"
    );
    assert!(
        saw_opaque_runtime,
        "the runtime rows must STAY opaque method:try_fold (not fabricated)"
    );
    assert_warranted_decls_not_refuted(&out, "runtime_try_fold_followup_read");
    assert!(
        out.skip_reasons
            .iter()
            .any(|r| r.contains("unknown iterator consumption")),
        "post-try_fold/try_rfold iterator reads must be named-refused, not checked \
         against stale literal state: {:?}",
        out.skip_reasons
    );

    let out = lift_one(
        r#"#[test]
fn test_by_ref_terminal_followup_read() {
    let mut xs = 0..10;
    let partial_sum = xs.by_ref().take(5).fold(0, |acc, x| acc + x);
    assert_eq!(partial_sum, 10);
    assert_eq!(xs.next(), Some(5));
}"#,
    );
    // `by_ref` keeps `xs` usable after the terminal has advanced it; without
    // a named refusal the later read is checked against stale initial state.
    assert_warranted_decls_not_refuted(&out, "by_ref_terminal_followup_read");
    assert!(
        out.skip_reasons
            .iter()
            .any(|r| r.contains("unknown iterator consumption") && r.contains("xs")),
        "post-by_ref terminal reads of xs must be named-refused, not checked against \
         stale literal state: {:?}",
        out.skip_reasons
    );

    let out = lift_one(
        r#"#[test]
fn test_by_ref_adaptor_binding_followup_terminal() {
    let xs = [0, 1, 2, 3, 4, 5];
    let mut it = xs.iter();
    {
        let mut take = it.by_ref().take(3);
        while let Some(_x) = take.nth(0) {}
    }
    assert_eq!(it.nth(1), Some(&5));
}"#,
    );
    // A `by_ref()` adaptor bound to another local can consume the original iterator by
    // a loop-dependent amount; the later direct terminal must not replay stale `it`.
    assert_warranted_decls_not_refuted(&out, "by_ref_adaptor_binding_followup_terminal");
    assert!(
        out.skip_reasons
            .iter()
            .any(|r| r.contains("unknown iterator consumption") && r.contains("it")),
        "post-by_ref adaptor terminal reads of it must be named-refused, not checked \
         against stale literal state: {:?}",
        out.skip_reasons
    );

    let out = lift_one(
        r#"#[test]
fn test_peekable_next_if_map_followup_peek() {
    fn collatz((mut num, mut len): (u64, u32)) -> Result<u32, (u64, u32)> {
        let jump = num.trailing_zeros();
        num >>= jump;
        len += jump;
        if num == 1 { Ok(len) } else { Err((3 * num + 1, len + 1)) }
    }

    let mut iter = std::iter::once((3, 0)).peekable();
    assert_eq!(iter.peek(), Some(&(3, 0)));
    assert_eq!(iter.next_if_map(collatz), None);
    assert_eq!(iter.peek(), Some(&(10, 1)));
}"#,
    );
    assert_warranted_decls_not_refuted(&out, "peekable_next_if_map_followup_peek");
    assert!(
        out.skip_reasons
            .iter()
            .any(|r| r.contains("unknown iterator consumption") && r.contains("iter")),
        "post-next_if_map peeks must be named-refused, not checked against stale \
         peekable state: {:?}",
        out.skip_reasons
    );

    let out = lift_one(
        r#"#[test]
fn test_try_find() {
    let xs: &[isize] = &[];
    assert_eq!(xs.iter().try_find(testfn), Ok(None));
    let xs: &[isize] = &[1, 2, 3, 4];
    assert_eq!(xs.iter().try_find(testfn), Ok(Some(&2)));
    let xs: &[isize] = &[1, 3, 4];
    assert_eq!(xs.iter().try_find(testfn), Err(()));

    let xs: &[isize] = &[1, 2, 3, 4, 5, 6, 7];
    let mut iter = xs.iter();
    assert_eq!(iter.try_find(testfn), Ok(Some(&2)));
    assert_eq!(iter.try_find(testfn), Err(()));
    assert_eq!(iter.next(), Some(&5));

    fn testfn(x: &&isize) -> Result<bool, ()> {
        if **x == 2 {
            return Ok(true);
        }
        if **x == 4 {
            return Err(());
        }
        Ok(false)
    }
}"#,
    );
    assert_warranted_decls_not_refuted(&out, "runtime_try_find_followup_read");
    assert!(
        out.skip_reasons
            .iter()
            .any(|r| r.contains("unknown iterator consumption")),
        "post-try_find iterator reads must be named-refused, not checked against stale \
         literal state: {:?}",
        out.skip_reasons
    );
}

