        assert!(good, "format!(\"{{}}\", 'a') == \"a\" must be SAT");
        let bad = format_eq_verdict(r#"format!("{}", 'a')"#, r#""b""#, "char_bad").unwrap();
        assert!(!bad, "wrong char string must be z3-UNSAT (teeth)");
