#[test]
fn ssa_rebind_let_chain_keeps_callsite_contract_boundary() {
    let src = r#"
fn other(x: i32) -> i32 { x + 10 }
fn h(x: i32) -> i32 { let x = other(x); x }

#[test]
fn calls_h() {
    assert_eq!(h(5), 15);
}
"#;
    let out = lift_file(&parse(src), "tests/inline.rs");
    let caller = warranted_decls(&out)
        .into_iter()
        .find(|decl| decl.name.contains("::calls_h::h#euf#"))
        .unwrap_or_else(|| panic!("missing caller h(5) fact: {:?}", out.decls));
    assert_call_eq_int(caller, "call:h", &[5], 15);
    assert!(
        out.decls
            .iter()
            .any(|decl| decl.name == "tests/inline.rs::h"),
        "h should keep its own source contract: {:?}",
        out.decls
    );
    assert!(!out.reduced_helpers.contains("h") && !out.reduced_helpers.contains("other"));
}

#[test]
fn no_source_call_stays_opaque_call_ctor() {
    // A call to a fn with NO in-source body has nothing to peel: it stays the honest
    // opaque `call:` ctor under its EUF callsite key, and is NOT recorded as support.
    let src = r#"
#[test]
fn calls_extern() {
    assert_eq!(extern_fn(2), 3);
}
"#;
    let out = lift_file(&parse(src), "tests/inline.rs");
    assert_warranted_decl_count(&out, 1);
    let (lhs, _rhs) = single_eq_atom(single_warranted_decl(&out));
    match lhs.as_ref() {
        Term::Ctor { name, .. } => assert_eq!(
            name, "call:extern_fn",
            "a no-source call must stay the opaque `call:` ctor"
        ),
        other => panic!("expected opaque `call:extern_fn`, got {other:?}"),
    }
    assert!(
        !out.reduced_helpers.contains("extern_fn"),
        "a no-source call peels nothing -> not a support member"
    );
}

#[test]
fn effect_body_bails_to_opaque_call_ctor() {
    // A helper whose body has an EFFECT (a `Vec::push` mutation) does not ground to a
    // value: the peel BAILS, leaving the opaque `call:h` ctor. The helper is NOT
    // recorded as support (it was not inlined) -- so it keeps its own broad contract.
    let src = r#"
fn h(n: i32) -> i32 { let mut v = Vec::new(); v.push(n); v.len() as i32 }

#[test]
fn calls_h() {
    assert_eq!(h(2), 1);
}
"#;
    let out = lift_file(&parse(src), "tests/inline.rs");
    assert_warranted_decl_count(&out, 1);
    let (lhs, _rhs) = single_eq_atom(single_warranted_decl(&out));
    match lhs.as_ref() {
        Term::Ctor { name, .. } => assert_eq!(
            name, "call:h",
            "an effect-body helper must BAIL to the opaque `call:h` ctor"
        ),
        other => panic!("expected opaque `call:h`, got {other:?}"),
    }
    assert!(
        !out.reduced_helpers.contains("h"),
        "a BAILED helper is NOT a support member (it keeps its own contract)"
    );
}

#[test]
fn async_fn_call_bails_value_peel_keeps_await_boundary() {
    // SOUNDNESS: an `async fn`'s body is the future's awaited output, NOT the call's
    // value. A non-awaited call to an async fn must NOT peel its body (that would
    // collapse the `.await` boundary) -- it stays the opaque `call:` ctor.
    let src = r#"
async fn h(n: i32) -> i32 { n + 1 }

#[test]
fn calls_h() {
    let _ = h(2);
    assert_eq!(awaited(), 3);
}

fn awaited() -> i32 { opaque() }
"#;
    let out = lift_file(&parse(src), "tests/inline.rs");
    // `h` must not be peeled to support (async body is not the call's value).
    assert!(
        !out.reduced_helpers.contains("h"),
        "an async fn must not be value-peeled (its body is the awaited output)"
    );
}

#[test]
fn recursive_fn_call_bails_to_opaque_via_depth_guard() {
    // A self-recursive fn cannot ground (it never bottoms out in literals); the inline
    // depth guard bails it to the opaque `call:` ctor rather than looping.
    let src = r#"
fn rec(n: i32) -> i32 { rec(n) + 1 }

#[test]
fn calls_rec() {
    assert_eq!(rec(2), 3);
}
"#;
    let out = lift_file(&parse(src), "tests/inline.rs");
    assert_warranted_decl_count(&out, 1);
    assert!(
        inv_has_opaque_call_leaf(single_warranted_decl(&out)),
        "a recursive fn must bail to the opaque `call:` ctor (depth guard)"
    );
    assert!(!out.reduced_helpers.contains("rec"));
}

#[test]
fn term_inline_contradictory_anchors_are_caught_not_masked() {
    // MASKED-CONTRADICTION GUARD (term-path port of the headstart statement-path guard).
    // Two asserts pin the SAME peeled value `h(2) = +(2,1)` to DISTINCT anchors (3 and
    // 4). Both must land in ONE coalesced inv so the conjunction is z3-UNSAT (CAUGHT) --
    // never two split obligations that each look fine on their own.
    let src = r#"
fn h(n: i32) -> i32 { n + 1 }

#[test]
fn contradiction() {
    assert_eq!(h(2), 3);
    assert_eq!(h(2), 4);
}
"#;
    let out = lift_file(&parse(src), "tests/inline.rs");
    assert_warranted_decl_count(&out, 1);
    let decl = single_warranted_decl(&out);
    let operands = inv_operands(decl);
    assert_eq!(
        operands.len(),
        2,
        "both contradictory pins must be present (not masked)"
    );
    // The whole conjoined contract is z3-UNSAT: `+(2,1)==3 && +(2,1)==4` cannot hold.
    if let Some(sat) = z3_verdict(&inv_json(decl), "inline_contradiction") {
        assert!(
            !sat,
            "the conjoined `+(2,1)==3 && +(2,1)==4` must be z3-UNSAT (contradiction caught)"
        );
    }
}

// ───────────────────────────────────────────────────────────────────────────
// IR-DOCUMENT CONTRACT (capability #1, part C): the peel must surface correctly
// through the `lift` RPC, not just the term-lift. A visible value helper owns a source
// contract even when a local value peel can compute the caller-side scalar fact. The
// caller keeps the callsite obligation (`call:h(2) == 3`); the helper owns its post; the
// linker/implication lifter composes them. A BAILED helper keeps its own broad contract too.
// ───────────────────────────────────────────────────────────────────────────

/// Run the RPC binary against a temp workspace holding one fixture file, returning the
/// `lift` result (the ir-document). Drives `initialize` + `lift` + `shutdown` over the
/// line-delimited JSON-RPC stdin protocol the binary speaks.
fn run_rpc_lift(rel_path: &str, source: &str) -> serde_json::Value {
    use std::io::Write;
    let dir = std::env::temp_dir().join(format!(
        "sugar_rpc_irdoc_{}_{}",
        std::process::id(),
        rel_path.replace('/', "_")
    ));
    let _ = std::fs::remove_dir_all(&dir);
    let file = dir.join(rel_path);
    std::fs::create_dir_all(file.parent().unwrap()).expect("mkdir");
    std::fs::write(&file, source).expect("write fixture");

    let req = format!(
        "{}\n{}\n{}\n",
        serde_json::json!({"jsonrpc":"2.0","id":1,"method":"initialize","params":{}}),
        serde_json::json!({"jsonrpc":"2.0","id":2,"method":"lift","params":{
            "workspace_root": dir.to_str().unwrap(),
            "source_paths": [rel_path],
        }}),
        serde_json::json!({"jsonrpc":"2.0","id":3,"method":"shutdown","params":{}}),
    );

    let mut child = std::process::Command::new(env!("CARGO_BIN_EXE_rust_test_assertions_rpc"))
        .stdin(std::process::Stdio::piped())
        .stdout(std::process::Stdio::piped())
        .spawn()
        .expect("spawn rpc bin");
    child
        .stdin
        .take()
        .unwrap()
        .write_all(req.as_bytes())
        .expect("write rpc req");
    let out = child.wait_with_output().expect("rpc bin output");
    let _ = std::fs::remove_dir_all(&dir);
    let stdout = String::from_utf8_lossy(&out.stdout);
    // The `lift` reply is the line carrying `"id":2`.
    for line in stdout.lines() {
        let v: serde_json::Value = match serde_json::from_str(line) {
            Ok(v) => v,
            Err(_) => continue,
        };
        if v.get("id") == Some(&serde_json::json!(2)) {
            return v["result"].clone();
        }
    }
    panic!("no `lift` (id:2) reply in rpc output:\n{stdout}");
}

fn run_rpc_lift_with_config(rel_path: &str, source: &str, config: &str) -> serde_json::Value {
    use std::io::Write;
    let dir = std::env::temp_dir().join(format!(
        "sugar_rpc_irdoc_cfg_{}_{}",
        std::process::id(),
        rel_path.replace('/', "_")
    ));
    let _ = std::fs::remove_dir_all(&dir);
    let file = dir.join(rel_path);
    std::fs::create_dir_all(file.parent().unwrap()).expect("mkdir source parent");
    std::fs::create_dir_all(dir.join(".sugar")).expect("mkdir .sugar");
    std::fs::write(&file, source).expect("write fixture");
    std::fs::write(dir.join(".sugar/config.toml"), config).expect("write config");

    let req = format!(
        "{}\n{}\n{}\n",
        serde_json::json!({"jsonrpc":"2.0","id":1,"method":"initialize","params":{}}),
        serde_json::json!({"jsonrpc":"2.0","id":2,"method":"lift","params":{
            "workspace_root": dir.to_str().unwrap(),
            "source_paths": [rel_path],
        }}),
        serde_json::json!({"jsonrpc":"2.0","id":3,"method":"shutdown","params":{}}),
    );

    let mut child = std::process::Command::new(env!("CARGO_BIN_EXE_rust_test_assertions_rpc"))
        .stdin(std::process::Stdio::piped())
        .stdout(std::process::Stdio::piped())
        .spawn()
        .expect("spawn rpc bin");
    child
        .stdin
        .take()
        .unwrap()
        .write_all(req.as_bytes())
        .expect("write rpc req");
    let out = child.wait_with_output().expect("rpc bin output");
    let _ = std::fs::remove_dir_all(&dir);
    let stdout = String::from_utf8_lossy(&out.stdout);
    for line in stdout.lines() {
        let v: serde_json::Value = match serde_json::from_str(line) {
            Ok(v) => v,
            Err(_) => continue,
        };
        if v.get("id") == Some(&serde_json::json!(2)) {
            return v["result"].clone();
        }
    }
    panic!("no `lift` (id:2) reply in rpc output:\n{stdout}");
}

/// The `status` of a named fn locus in a `lift` ir-document, or None if absent.
fn locus_status<'a>(doc: &'a serde_json::Value, fn_name: &str) -> Option<&'a str> {
    doc["sourceAudits"]
        .as_array()?
        .iter()
        .flat_map(|a| a["loci"].as_array().into_iter().flatten())
        .find(|l| l["ast_path"] == serde_json::json!(fn_name))
        .and_then(|l| l["status"].as_str())
}

/// The refusal/warrant reason of a named fn locus in a `lift` ir-document.
fn locus_reason<'a>(doc: &'a serde_json::Value, fn_name: &str) -> Option<&'a str> {
    doc["sourceAudits"]
        .as_array()?
        .iter()
        .flat_map(|a| a["loci"].as_array().into_iter().flatten())
        .find(|l| l["ast_path"] == serde_json::json!(fn_name))
        .and_then(|l| l["reason"].as_str())
}

fn assert_rpc_source_refused(doc: &serde_json::Value, fn_name: &str, category: &str) {
    assert_eq!(
        locus_status(doc, fn_name),
        Some("refused"),
        "{fn_name} must be named-refused: {doc:#}"
    );
    let reason = locus_reason(doc, fn_name).unwrap_or("");
    assert!(
        reason.contains(category),
        "{fn_name} refusal must carry category {category:?}, got {reason:?}: {doc:#}"
    );
    assert!(
        !reason.contains("refuted"),
        "{fn_name} must refuse by name, not refute: {reason}"
    );
}

fn assert_rpc_source_inactive(doc: &serde_json::Value, fn_name: &str, category: &str) {
    assert_eq!(
        locus_status(doc, fn_name),
        Some("inactive"),
        "{fn_name} must be marked inactive: {doc:#}"
    );
    let reason = locus_reason(doc, fn_name).unwrap_or("");
    assert!(
        reason.contains(category),
        "{fn_name} inactive reason must carry category {category:?}, got {reason:?}: {doc:#}"
    );
}

fn assert_rpc_source_warranted(doc: &serde_json::Value, fn_name: &str) {
    assert_eq!(
        locus_status(doc, fn_name),
        Some("warranted"),
        "{fn_name} is the value-in-text twin and must still warrant: {doc:#}"
    );
}

#[test]
fn ip_addr_literal_property_predicates_have_teeth() {
    let good = r#"
        use core::net::IpAddr;
        use core::str::FromStr;

        #[test]
        fn ip_literal_good() {
            assert!(IpAddr::from_str("127.0.0.1").unwrap().is_loopback());
        }
    "#;
    let good_out = lift_file(&parse(good), "tests/net/ip_literal_good.rs");
    assert_eq!(
        good_out.assertions_lifted, 1,
        "literal IpAddr property should warrant; skips={:?}; audits={:?}",
        good_out.skip_reasons, good_out.factory_audits
    );
    if let Some(sat) = z3_verdict(
        &inv_json(single_warranted_decl(&good_out)),
        "ip_literal_good",
    ) {
        assert!(sat, "127.0.0.1 is loopback");
    }

    let bad = r#"
        use core::net::IpAddr;
        use core::str::FromStr;

        #[test]
        fn ip_literal_bad() {
            assert!(IpAddr::from_str("127.0.0.1").unwrap().is_global());
        }
    "#;
    let bad_out = lift_file(&parse(bad), "tests/net/ip_literal_bad.rs");
    assert_eq!(
        bad_out.assertions_lifted, 1,
        "bad twin must still lift so z3 can bite; skips={:?}; audits={:?}",
        bad_out.skip_reasons, bad_out.factory_audits
    );
    if let Some(sat) = z3_verdict(&inv_json(single_warranted_decl(&bad_out)), "ip_literal_bad") {
        assert!(!sat, "127.0.0.1 is not global");
    }
}

#[test]
fn rpc_source_warrants_macro_wrapped_literal_ip_properties() {
    let doc = run_rpc_lift(
        "tests/net/ip_addr.rs",
        r#"
use core::net::IpAddr;
use core::str::FromStr;

#[test]
fn ip_properties() {
    macro_rules! ip {
        ($s:expr) => {
            IpAddr::from_str($s).unwrap()
        };
    }

    macro_rules! check {
        ($s:expr, $mask:expr) => {{
            let loopback: u8 = 1 << 1;
            if ($mask & loopback) == loopback {
                assert!(ip!($s).is_loopback());
            } else {
                assert!(!ip!($s).is_loopback());
            }
        }};
    }

    check!("127.0.0.1", 1 << 1);
}

#[test]
fn literal_ip_twin() {
    assert!(IpAddr::from_str("127.0.0.1").unwrap().is_loopback());
}
"#,
    );

    assert_rpc_source_warranted(&doc, "ip_properties");
    assert_rpc_source_warranted(&doc, "literal_ip_twin");
}

