/// True iff any `ir` entry's serialized form mentions the opaque `call:<name>` symbol --
/// i.e. a standalone `out=call:<name>` warrant decl was minted into the ir-document.
fn ir_mentions_call_symbol(doc: &serde_json::Value, name: &str) -> bool {
    let needle = format!("call:{name}");
    doc["ir"]
        .as_array()
        .map(|arr| arr.iter().any(|e| e.to_string().contains(&needle)))
        .unwrap_or(false)
}

/// The first `ir` index whose serialized entry mentions `needle`.
fn ir_entry_index_containing(doc: &serde_json::Value, needle: &str) -> Option<usize> {
    doc["ir"]
        .as_array()?
        .iter()
        .position(|entry| entry.to_string().contains(needle))
}

/// The first `ir` entry whose contract/function-contract name is `name`.
fn ir_entry_named<'a>(doc: &'a serde_json::Value, name: &str) -> Option<&'a serde_json::Value> {
    doc["ir"].as_array()?.iter().find(|entry| {
        matches!(
            entry["kind"].as_str(),
            Some("contract" | "function-contract")
        ) && entry["name"] == serde_json::json!(name)
    })
}

fn call_edge_named<'a>(
    doc: &'a serde_json::Value,
    source: &str,
    target_symbol: &str,
    target: &str,
) -> Option<&'a serde_json::Value> {
    doc["callEdges"].as_array()?.iter().find(|edge| {
        edge["sourceContract"] == serde_json::json!(source)
            && edge["targetSymbol"] == serde_json::json!(target_symbol)
            && edge["targetContract"] == serde_json::json!(target)
    })
}

fn assert_contract_edge(doc: &serde_json::Value, source: &str, symbol: &str, target: &str) {
    let edge = call_edge_named(doc, source, symbol, target)
        .unwrap_or_else(|| panic!("missing call edge {source} -> {symbol} -> {target}: {doc:#}"));
    assert_eq!(edge["kind"], serde_json::json!("call-edge"));
    for key in ["sourceContractCid", "targetContractCid"] {
        let cid = edge[key]
            .as_str()
            .unwrap_or_else(|| panic!("{key} missing from edge: {edge:#}"));
        assert!(
            cid.starts_with("blake3-512:"),
            "{key} must be a prefixed CID, got {cid}: {edge:#}"
        );
    }
}

#[test]
fn rpc_source_warrants_no_scalar_literal_aggregate_macro_not_supports() {
    let rel = "src/source_no_scalar_array_try_from.rs";
    let src = r#"
#[test]
fn no_scalar_array_try_from_support() {
    macro_rules! test {
        ($($N:expr)+) => {
            $({
                type Array = [u8; $N];
                let mut array: Array = [0; $N];
                let slice: &[u8] = &array[..];

                let result = <&Array>::try_from(slice);
                assert_eq!(&array, result.unwrap());

                let result = <Array>::try_from(slice);
                assert_eq!(&array, &result.unwrap());

                let mut_slice: &mut [u8] = &mut array[..];
                let result = <&mut Array>::try_from(mut_slice);
                assert_eq!(&[0; $N], result.unwrap());

                let mut_slice: &mut [u8] = &mut array[..];
                let result = <Array>::try_from(mut_slice);
                assert_eq!(&array, &result.unwrap());
            })+
        }
    }
    test! { 0 1 2 }
}

#[test]
fn no_scalar_array_try_from_literal_twin() {
    assert_eq!(1usize, 1usize);
}
"#;
    let out = lift_file(&parse(src), rel);
    assert!(
        out.assertions_lifted > 0 && out.warnings.is_empty(),
        "in-process lift must reach the literal aggregate before RPC ledgering; lifted={} refused={} warnings={:?} facts={:?} decls={:?}",
        out.assertions_lifted,
        out.assertions_refused,
        out.warnings,
        out.assertion_facts,
        out.decls.iter().map(|decl| decl.name.as_str()).collect::<Vec<_>>()
    );
    let doc = run_rpc_lift(rel, src);
    assert_rpc_source_warranted(&doc, "no_scalar_array_try_from_support");
    assert_rpc_source_warranted(&doc, "no_scalar_array_try_from_literal_twin");
}

