#[test]
fn rpc_reduced_value_helper_keeps_contract_and_callsite_edge() {
    let doc = run_rpc_lift(
        "src/value_helper_edge.rs",
        r#"
fn h(n: i32) -> i32 { n + 1 }

#[test]
fn calls_h() {
    assert_eq!(h(2), 3);
}
"#,
    );

    assert_eq!(
        locus_status(&doc, "h"),
        Some("warranted"),
        "a visible helper owns a source contract even when the caller fact can be reduced: {doc:#}"
    );
    let helper = ir_entry_named(&doc, "rust-source::h")
        .unwrap_or_else(|| panic!("missing source contract for h: {doc:#}"));
    assert_eq!(helper["kind"], serde_json::json!("function-contract"));
    assert_eq!(helper["bridgeSourceSymbol"], serde_json::json!("call:h"));
    assert!(
        helper.get("post").is_some(),
        "helper must own its postcondition, not donate its body to the caller: {helper:#}"
    );

    let callsite_fact = doc["ir"]
        .as_array()
        .and_then(|entries| {
            entries.iter().find(|entry| {
                entry["kind"] == serde_json::json!("contract")
                    && entry["name"]
                        .as_str()
                        .is_some_and(|name| name.contains("::h#euf#"))
                    && entry["inv"].to_string().contains("call:h")
            })
        })
        .unwrap_or_else(|| panic!("missing caller-owned callsite fact for h(2): {doc:#}"));
    let source_contract = callsite_fact["name"]
        .as_str()
        .expect("callsite fact has a name");
    assert!(
        callsite_fact["inv"].to_string().contains("call:h")
            && !callsite_fact["inv"].to_string().contains("panic"),
        "caller value fact must retain the base callsite term, with panic support split out: {callsite_fact:#}"
    );
    let panic_support = doc["ir"]
        .as_array()
        .and_then(|entries| {
            entries.iter().find(|entry| {
                entry["kind"] == serde_json::json!("contract")
                    && entry["name"]
                        .as_str()
                        .is_some_and(|name| name.contains("::h#panic_callsite#"))
            })
        })
        .unwrap_or_else(|| panic!("missing caller-owned panic support fact for h(2): {doc:#}"));
    assert!(
        panic_support["inv"].to_string().contains("panic")
            && panic_support["inv"]
                .to_string()
                .contains("call:h#panic_callsite"),
        "panic support must own the opaque panic-callsite term: {panic_support:#}"
    );
    assert_contract_edge(&doc, source_contract, "call:h", "rust-source::h");
}

#[test]
fn rpc_unit_driver_emits_callable_param_precondition_bridge() {
    // `driver` returns unit, so the old value-output rule had no contract to mint.
    // But the body calls the callable parameter `f`; normal return from `driver(f)`
    // therefore carries a real bridge precondition: `f()` returned normally. The
    // closure body is not anonymously inlined here; the report must expose the
    // source contract that the callsite support fact warrants digging into.
    let doc = run_rpc_lift(
        "src/driver_bridge.rs",
        r#"
fn driver<F: Fn()>(f: F) {
    f();
}

#[test]
fn caller() {
    driver(|| {
        assert_eq!(1, 1);
    });
}
"#,
    );

    assert_eq!(
        locus_status(&doc, "driver"),
        Some("warranted"),
        "unit driver callsites still warrant a source contract: {doc:#}"
    );
    let driver = ir_entry_named(&doc, "rust-source::driver")
        .unwrap_or_else(|| panic!("missing driver function contract: {doc:#}"));
    assert_eq!(driver["kind"], serde_json::json!("function-contract"));
    assert_eq!(
        driver["bridgeSourceSymbol"],
        serde_json::json!("call:driver")
    );
    assert!(
        driver["pre"].to_string().contains("call:f") && driver["pre"].to_string().contains("panic"),
        "driver precondition must expose the callable-parameter panic-free bridge: {driver:#}"
    );
    let driver_edge = doc["callEdges"]
        .as_array()
        .and_then(|edges| {
            edges.iter().find(|edge| {
                edge["targetSymbol"] == serde_json::json!("call:driver")
                    && edge["targetContract"] == serde_json::json!("rust-source::driver")
            })
        })
        .unwrap_or_else(|| {
            panic!("caller support fact must bridge into the driver source contract: {doc:#}")
        });
    assert!(
        driver_edge["evidenceTerm"]
            .to_string()
            .contains("call:driver#panic_callsite"),
        "the bridge evidence keeps the sort-safe opaque panic-callsite term: {driver_edge:#}"
    );
}

#[test]
fn closure_driver_invocation_recurses_body_per_temporal_callsite() {
    let src = r#"
fn driver<F: Fn()>(f: F) {
    f();
    f();
}

#[test]
fn caller() {
    driver(|| {
        assert_eq!(probe(), 1);
    });
}
"#;
    let out = lift_file(&parse(src), "tests/closure_driver.rs");
    assert_eq!(out.assertions_refused, 0, "{:?}", out.skip_reasons);
    assert_eq!(
        out.assertions_lifted, 2,
        "closure body should recurse once per f() callsite: {:?}",
        out
    );
    let probe_decls: Vec<_> = warranted_decls(&out)
        .into_iter()
        .filter(|decl| decl.name.contains("probe"))
        .collect();
    assert_eq!(
        probe_decls.len(),
        2,
        "each temporal closure invocation should own a probe fact: {:?}",
        out.decls
    );
    assert_ne!(
        probe_decls[0].name, probe_decls[1].name,
        "temporal closure invocations must not collapse into one contract"
    );
}

#[test]
fn direct_closure_invocation_recurses_body() {
    let src = r#"
#[test]
fn caller() {
    (|| {
        assert_eq!(probe(), 1);
    })();
}
"#;
    let out = lift_file(&parse(src), "tests/direct_closure.rs");
    assert_eq!(out.assertions_refused, 0, "{:?}", out.skip_reasons);
    assert_eq!(
        out.assertions_lifted, 1,
        "direct closure invocation should hand the body back to the collector: {:?}",
        out
    );
}

#[test]
fn rpc_emits_consumed_impl_methods_as_bridgeable_contracts() {
    // `Maker::new` and `Maker::get` are consumed by the recursive method DFS that
    // grounds the regex pattern. They still own source semantics: the lifter must emit
    // bridgeable method contracts keyed by the same `Type::method` identity the method
    // registry used, not bury them as support-only universe members.
    let doc = run_rpc_lift(
        "src/method_inline.rs",
        r#"
struct Maker {
    pattern: &'static str,
}

impl Maker {
    fn new(pattern: &'static str) -> Self {
        Self { pattern }
    }

    fn get(&self) -> &'static str {
        let x = self.pattern;
        x
    }
}

#[test]
fn regex_from_method() {
    let m = Maker::new("blah");
    assert!(Regex::new(m.get()).unwrap().is_match("blah"));
}
"#,
    );

    assert_eq!(
        locus_status(&doc, "Maker::new"),
        Some("warranted"),
        "consumed associated constructor must carry its own source contract: {doc:#}"
    );
    assert_eq!(
        locus_status(&doc, "Maker::get"),
        Some("warranted"),
        "consumed receiver method must carry its own source contract: {doc:#}"
    );
    assert_eq!(
        doc["sourceLedger"]["source_warranted"],
        serde_json::json!(2),
        "both consumed impl methods should count as source-warranted; assertion surfaces are accounted separately: {doc:#}"
    );
    let new_contract = ir_entry_named(&doc, "rust-source::Maker::new")
        .unwrap_or_else(|| panic!("missing Maker::new contract: {doc:#}"));
    let get_contract = ir_entry_named(&doc, "rust-source::Maker::get")
        .unwrap_or_else(|| panic!("missing Maker::get contract: {doc:#}"));
    assert_eq!(new_contract["kind"], serde_json::json!("function-contract"));
    assert_eq!(
        new_contract["bridgeSourceSymbol"],
        serde_json::json!("call:Maker::new")
    );
    assert_eq!(get_contract["kind"], serde_json::json!("function-contract"));
    assert_eq!(
        get_contract["bridgeSourceSymbol"],
        serde_json::json!("method:get")
    );
}

#[test]
fn rpc_method_contracts_carry_recursive_contract_edges() {
    // x() calls y(), y() calls z(), z() returns a literal-backed field. The report must
    // not collapse x/y/z into source support. x owns "x AND y" by emitting its local
    // body relation `out = method:y(self)` plus a bridgeable contract for y; y does the
    // same for z.
    let doc = run_rpc_lift(
        "src/method_edges.rs",
        r#"
struct Maker {
    pattern: &'static str,
}

impl Maker {
    fn new(pattern: &'static str) -> Self {
        Self { pattern }
    }

    fn x(&self) -> &'static str {
        self.y()
    }

    fn y(&self) -> &'static str {
        self.z()
    }

    fn z(&self) -> &'static str {
        let x = self.pattern;
        x
    }
}

#[test]
fn regex_from_method_chain() {
    let m = Maker::new("blah");
    assert!(Regex::new(m.x()).unwrap().is_match("blah"));
}
"#,
    );

    for name in ["Maker::x", "Maker::y", "Maker::z"] {
        assert_eq!(
            locus_status(&doc, name),
            Some("warranted"),
            "{name} must be a source contract, not support-only: {doc:#}"
        );
        let contract = ir_entry_named(&doc, &format!("rust-source::{name}"))
            .unwrap_or_else(|| panic!("missing method contract for {name}: {doc:#}"));
        assert_eq!(
            contract["kind"],
            serde_json::json!("function-contract"),
            "{name} must mint as a body-bearing function contract: {contract:#}"
        );
        assert_eq!(
            contract["sourceWarrants"][0]["sourceFunctionName"],
            serde_json::json!(name),
            "{name} must carry its own source memento warrant: {contract:#}"
        );
    }

    let x = ir_entry_named(&doc, "rust-source::Maker::x").unwrap();
    let y = ir_entry_named(&doc, "rust-source::Maker::y").unwrap();
    let z = ir_entry_named(&doc, "rust-source::Maker::z").unwrap();
    assert_eq!(x["bridgeSourceSymbol"], serde_json::json!("method:x"));
    assert!(
        x["post"].to_string().contains("method:y"),
        "x's contract must carry the edge to y: {x:#}"
    );
    assert_eq!(y["bridgeSourceSymbol"], serde_json::json!("method:y"));
    assert!(
        y["post"].to_string().contains("method:z"),
        "y's contract must carry the edge to z: {y:#}"
    );
    assert_eq!(z["bridgeSourceSymbol"], serde_json::json!("method:z"));
    assert!(
        z["post"].to_string().contains("field:pattern"),
        "z must bottom out at the field relation: {z:#}"
    );
    assert_contract_edge(
        &doc,
        "rust-source::Maker::x",
        "method:y",
        "rust-source::Maker::y",
    );
    assert_contract_edge(
        &doc,
        "rust-source::Maker::y",
        "method:z",
        "rust-source::Maker::z",
    );
}

#[test]
fn rpc_matcher_method_contracts_carry_recursive_argument_edges() {
    // MatcherMethod::x("blah") calls y(input), y(input) calls z(input), and z(input)
    // returns that same input. This is the argument-threaded version of the recursive
    // method contract edge: the source contracts must carry `method:y(self, input)`
    // and `method:z(self, input)`, not collapse to receiver-only edges.
    let doc = run_rpc_lift(
        "src/matcher_method_edges.rs",
        r#"
struct MatcherMethod;

impl MatcherMethod {
    fn x(&self, input: &'static str) -> &'static str {
        self.y(input)
    }

    fn y(&self, input: &'static str) -> &'static str {
        self.z(input)
    }

    fn z(&self, input: &'static str) -> &'static str {
        input
    }
}

#[test]
fn regex_from_matcher_method_chain() {
    let m = MatcherMethod;
    assert!(Regex::new(m.x("blah")).unwrap().is_match("blah"));
}
"#,
    );

    for name in ["MatcherMethod::x", "MatcherMethod::y", "MatcherMethod::z"] {
        assert_eq!(
            locus_status(&doc, name),
            Some("warranted"),
            "{name} must be a source contract, not support-only: {doc:#}"
        );
        let contract = ir_entry_named(&doc, &format!("rust-source::{name}"))
            .unwrap_or_else(|| panic!("missing method contract for {name}: {doc:#}"));
        assert_eq!(
            contract["kind"],
            serde_json::json!("function-contract"),
            "{name} must mint as a body-bearing function contract: {contract:#}"
        );
        assert_eq!(
            contract["formals"],
            serde_json::json!(["self", "input"]),
            "{name} must keep receiver + input slots for downstream vendor binding: {contract:#}"
        );
    }

    let x = ir_entry_named(&doc, "rust-source::MatcherMethod::x").unwrap();
    let y = ir_entry_named(&doc, "rust-source::MatcherMethod::y").unwrap();
    let z = ir_entry_named(&doc, "rust-source::MatcherMethod::z").unwrap();
    let x_post = x["post"].to_string();
    let y_post = y["post"].to_string();
    let z_post = z["post"].to_string();
    assert_eq!(x["bridgeSourceSymbol"], serde_json::json!("method:x"));
    assert!(
        x_post.contains("method:y") && x_post.contains("input"),
        "x's contract must carry the argument-threaded edge to y(input): {x:#}"
    );
    assert_eq!(y["bridgeSourceSymbol"], serde_json::json!("method:y"));
    assert!(
        y_post.contains("method:z") && y_post.contains("input"),
        "y's contract must carry the argument-threaded edge to z(input): {y:#}"
    );
    assert_eq!(z["bridgeSourceSymbol"], serde_json::json!("method:z"));
    assert!(
        z_post.contains("input") && !z_post.contains("method:"),
        "z must bottom out at the input relation, not another method edge: {z:#}"
    );
    assert_contract_edge(
        &doc,
        "rust-source::MatcherMethod::x",
        "method:y",
        "rust-source::MatcherMethod::y",
    );
    assert_contract_edge(
        &doc,
        "rust-source::MatcherMethod::y",
        "method:z",
        "rust-source::MatcherMethod::z",
    );
}

#[test]
fn rpc_emits_source_method_contract_before_caller_method_obligation() {
    // A method body we cannot ground still has a source contract. Emit that
    // callee contract first, then the caller assertion carrying `method:get`, so
    // downstream mint/link can reuse the callee memento instead of discovering it
    // after the caller-side obligation has already been serialized.
    let doc = run_rpc_lift(
        "src/method_order.rs",
        r#"
struct Maker;

impl Maker {
    fn get(&self) -> i32 {
        opaque()
    }
}

#[test]
fn caller() {
    let m = Maker;
    assert_eq!(m.get(), 3);
}
"#,
    );

    let callee = ir_entry_index_containing(&doc, "rust-source::Maker::get")
        .unwrap_or_else(|| panic!("missing source method contract: {doc:#}"));
    let caller = ir_entry_index_containing(&doc, "method:get#euf")
        .unwrap_or_else(|| panic!("missing caller method obligation: {doc:#}"));
    assert!(
        callee < caller,
        "source method contract must be emitted before caller obligation: callee={callee}, caller={caller}, doc={doc:#}"
    );
}

#[test]
fn rpc_bailed_helper_keeps_its_own_broad_contract() {
    // CONTRAST: an effect-bodied helper BAILS the peel, so it is NOT a support member --
    // it keeps its own broad-functional contract (`out=call:h`). This is the correct
    // non-inlined disposition: we did not inline it, so it stands as its own fixedpoint.
    let doc = run_rpc_lift(
        "src/inline_bail.rs",
        r#"
fn h(n: i32) -> i32 { let mut v = Vec::new(); v.push(n); v.len() as i32 }

#[test]
fn calls_h() {
    assert_eq!(h(2), 1);
}
"#,
    );
    assert_eq!(
        locus_status(&doc, "h"),
        Some("warranted"),
        "a BAILED helper keeps its own broad-functional warrant: {doc:#}"
    );
    assert!(
        ir_mentions_call_symbol(&doc, "h"),
        "a BAILED helper's own `out=call:h` contract must remain in the ir-document: {doc:#}"
    );
}

// --- catch_unwind let-initializer peel (the last coretests unclassified) ---
//
// The single coretests `--rustc-cfg` UNCLASSIFIED was an assert inside a
// `let <pat> = std::panic::catch_unwind(|| { ...; <recv>.map(|x| { assert..; .. }); });`
// initializer. The closure-adaptor recognizer is gated on the TOP-LEVEL expr being a
// `MethodCall`, but here the asserting closure-method (`recv.map(|x| { .. })`) is nested
// INSIDE a free-fn `catch_unwind(|| { .. })` wrapper, so the recognizer never reached it
// and the asserts fell to the GENERIC "let-initializer ... released to layer 0"
// UNCLASSIFIED reason (lifter WORK), not their true source-property boundary.
//
// `catch_unwind(closure)` invokes its closure UNCONDITIONALLY (it runs the body and
// catches any panic), so its body statements are reached on the same footing as a plain
// block: recursing the collector into the closure body gives every inner statement its
// honest disposition. The inner `let _ = recv.map(|x| { assert.. })` is then a
// `Stmt::Local` whose init IS a top-level `MethodCall`, so the existing
// `closure_method_terminal_effect` names the boundary (a side-effecting / runtime closure
// body) and TERMINALIZES it -- moving unclassified -> refused HONESTLY, never a fake-dig.

#[test]
fn catch_unwind_letinit_side_effecting_closure_body_terminalizes() {
    // array.rs::array_map_drop_safety, exact shape. The `.map` closure body does
    // `nth += 1` (mutates a captured local), so the asserted `nth` is a per-iteration
    // varying value -- not a single timeless point-wise claim. It must terminalize as a
    // SIDE-EFFECTING closure body (Disposition::Refused), NOT fake-lift and NOT stay the
    // generic unclassified let-initializer reason.
    let src = r#"
#[test]
fn t() {
    let num_to_create = 5;
    let success = std::panic::catch_unwind(|| {
        let items = [0; 10];
        let mut nth = 0;
        let _ = items.map(|_| {
            assert!(nth < num_to_create);
            nth += 1;
        });
    });
}
"#;
    let out = lift_file(&parse(src), "tests/array.rs");
    assert_eq!(
        out.assertions_lifted, 0,
        "a side-effecting (`nth += 1`) closure body must NOT lift -- the asserted value varies per iteration: {:?}",
        out.skip_reasons
    );
    // The reason must be the NAMED side-effecting-closure-body boundary, NOT the generic
    // let-initializer unclassified reason.
    assert!(
        !out
            .skip_reasons
            .iter()
            .any(|r| r.contains("let-initializer expression: not a top-level point-wise")),
        "the catch_unwind closure body must be PEELED, not left as the generic let-init unclassified reason: {:?}",
        out.skip_reasons
    );
    let reason = out
        .skip_reasons
        .iter()
        .find(|r| r.contains("side-effecting closure body"))
        .unwrap_or_else(|| {
            panic!(
                "expected a side-effecting-closure-body refusal, got {:?}",
                out.skip_reasons
            )
        });
    assert_eq!(
        sugar_lift_rust_tests::refusal_disposition(reason),
        sugar_lift_rust_tests::Disposition::Refused,
        "a side-effecting closure body is a TERMINAL source property (refused), not unclassified work: {:?}",
        out.skip_reasons
    );
}

#[test]
fn catch_unwind_letinit_runtime_receiver_closure_body_terminalizes() {
    // array.rs::array_map_drops_unmapped_elements_on_panic, shape. The `.map` receiver is
    // a runtime `array::from_fn(..)` aggregate (not a finite construction from source
    // literals), so the iterated `x` is runtime data. It must terminalize as a NAMED
    // runtime boundary (Disposition::Refused) through the catch_unwind peel, NOT fake-lift,
    // NOT the generic unclassified let-init reason.
    let src = r#"
#[test]
fn t() {
    let a = core::array::from_fn::<_, 11, _>(|i| i);
    let success = std::panic::catch_unwind(|| {
        let _ = a.map(|x| {
            assert!(x < 5);
        });
    });
}
"#;
    let out = lift_file(&parse(src), "tests/array.rs");
    assert_eq!(
        out.assertions_lifted, 0,
        "a `.map` over a runtime `from_fn` receiver must NOT lift -- the iterated value is runtime data: {:?}",
        out.skip_reasons
    );
    assert!(
        !out
            .skip_reasons
            .iter()
            .any(|r| r.contains("let-initializer expression: not a top-level point-wise")),
        "the catch_unwind closure body must be PEELED, not left as the generic let-init unclassified reason: {:?}",
        out.skip_reasons
    );
    // Every refusal it produces must be TERMINAL (a source property), never unclassified work.
    assert!(
        !out.skip_reasons.is_empty(),
        "the runtime closure body must be accounted (refused), not silent: {:?}",
        out.skip_reasons
    );
    for r in &out.skip_reasons {
        assert_eq!(
            sugar_lift_rust_tests::refusal_disposition(r),
            sugar_lift_rust_tests::Disposition::Refused,
            "every refusal under the peeled catch_unwind must be TERMINAL, not unclassified: {r:?}"
        );
    }
}

#[test]
fn catch_unwind_letinit_pure_inner_assert_digs_good_twin_and_bad_twin_unsat() {
    // DISCRIMINATION + TEETH (the bad-twin gate). The catch_unwind peel must be EXACT: a
    // genuinely point-wise inner assert over a closed literal still DIGS through the peel
    // (it is not fake-terminalized), and its lifted FOL is z3-refutable in the bad twin.
    //
    // GOOD twin: `let v = { 6 }; assert_eq!(v, 6);` inside the catch_unwind closure body --
    // a pure block-init local + a closed point-wise equality. It must LIFT (the peel does
    // not block a liftable inner claim), and the lifted atom `eq(6,6)` is SAT under z3.
    let good = r#"
#[test]
fn t() {
    let _ = std::panic::catch_unwind(|| {
        let v = { 6i32 };
        assert_eq!(v, 6i32);
    });
}
"#;
    let out_good = lift_file(&parse(good), "tests/array.rs");
    assert_eq!(
        out_good.assertions_lifted, 1,
        "a pure point-wise inner assert over a closed literal must DIG through the catch_unwind peel: {:?}",
        out_good.skip_reasons
    );
    if let Some(sat) = z3_verdict(&inv_json(&out_good.decls[0]), "catch_unwind_good") {
        assert!(
            sat,
            "the lifted `v == 6` (with v := 6) must be SAT under z3"
        );
    }

    // BAD twin: flip the anchor (`assert_eq!(v, 7)` with the same `v := 6`). The lifted
    // conjunction `v == 6 AND v == 7` is z3-UNSAT -- the teeth bite.
    let bad = r#"
#[test]
fn t() {
    let _ = std::panic::catch_unwind(|| {
        let v = { 6i32 };
        assert_eq!(v, 6i32);
        assert_eq!(v, 7i32);
    });
}
"#;
    let out_bad = lift_file(&parse(bad), "tests/array.rs");
    assert_eq!(
        out_bad.assertions_lifted, 2,
        "both inner asserts must lift through the peel so the contradiction is checkable: {:?}",
        out_bad.skip_reasons
    );
    if let Some(sat) = z3_verdict(&inv_json(&out_bad.decls[0]), "catch_unwind_bad") {
        assert!(
            !sat,
            "the bad twin `v == 6 AND v == 7` must be UNSAT under z3 (the anchor-flip teeth)"
        );
    }
}

