// ---------------------------------------------------------------------------
// SLICE-COERCION CAST (`&array as &[_]`): a cast to a slice reference is an UNSIZING
// coercion (`&[T; N] as &[T]`) -- value-preserving (the slice views the same elements),
// so `cast_term` desugars it transparently to the inner reference's term (like `as _`).
// Was the dominant cast_term dark shape: it backstopped, blocking the EUF-arg comparison
// `Clamp(r).get(&slice as &[_]) == other.get(&slice as &[_])`. (`cast_term` slice arm.)

#[test]
fn slice_coercion_cast_warrants_array_value() {
    let src = r#"
        #[test]
        fn t_slice_coerce() {
            assert_eq!(&[1, 2, 3] as &[_], &[1, 2, 3]);
        }
    "#;
    let out = lift_file(&parse(src), "coretests/cast/slice_coerce.rs");
    assert!(
        out.assertions_lifted >= 1 && out.assertions_refused == 0,
        "`&[1,2,3] as &[_] == &[1,2,3]` must warrant (transparent unsizing coercion): \
         lifted={} refused={} skips={:?}",
        out.assertions_lifted,
        out.assertions_refused,
        out.skip_reasons
    );
    if let Some(sat) = z3_verdict(&inv_json(&out.decls[0]), "slice_coerce_good") {
        assert!(
            sat,
            "&[1,2,3] as &[_] == &[1,2,3] -> the array equals itself (SAT)"
        );
    }
}

// Array/slice equality is a non-scalar assertion surface, but when both sides are
// text-determined it has scalar teeth: length plus element equalities. The slice coercion
// remains transparent, and the bad twin now refutes instead of sitting behind
// content-keyed aggregate vars.
#[test]
fn slice_coercion_cast_is_transparent_not_backstop() {
    let src = r#"
        #[test]
        fn t_slice_transparent() {
            assert_eq!(&[1, 2, 3] as &[_], &[1, 2, 3]);
        }
    "#;
    let out = lift_file(&parse(src), "coretests/cast/slice_transparent.rs");
    assert!(
        out.assertions_lifted >= 1 && out.assertions_refused == 0,
        "the slice coercion must be transparent (lifted, not refused): lifted={} \
         refused={} skips={:?}",
        out.assertions_lifted,
        out.assertions_refused,
        out.skip_reasons
    );
    assert!(
        !out.skip_reasons
            .iter()
            .any(|r| r.contains("unsupported term") && r.contains("as")),
        "`&[..] as &[_]` must NOT backstop as an unsupported cast: {:?}",
        out.skip_reasons
    );
}

// KIT BAD-TWIN: a genuinely false distinct-array equality must lift with scalar teeth and
// become z3-UNSAT. This is the non-scalar literal floor: the values are in the text, so
// leaving them as opaque aggregate vars would be an under-lift.
#[test]
fn kit_slice_coercion_distinct_arrays_refute_with_literal_teeth() {
    let src = r#"
        #[test]
        fn t_slice_bad_twin() {
            assert_eq!(&[10, 20, 30] as &[_], &[10, 20, 99]);
        }
    "#;
    let out = lift_file(&parse(src), "coretests/cast/slice_bad_twin.rs");
    // It must LIFT transparently (the cast is value-preserving; this is not a refuse).
    assert!(
        out.assertions_lifted >= 1 && out.assertions_refused == 0,
        "bad-twin must lift transparently (not refuse): lifted={} refused={} skips={:?}",
        out.assertions_lifted,
        out.assertions_refused,
        out.skip_reasons
    );
    let inv = inv_json(&out.decls[0]);
    let doc = sugar_ir_symbolic::serialize::marshal_declarations(&out.decls);
    assert!(
        !doc.contains("literal:Array("),
        "literal array equality should decompose to scalar teeth, not aggregate vars: {doc}"
    );
    if let Some(sat) = z3_verdict(&inv, "kit_slice_bad_twin_pos") {
        assert!(!sat, "distinct literal arrays must be z3-UNSAT");
    }
}

#[test]
fn array_try_from_unwrap_over_literal_slice_lifts_with_bad_twin() {
    let good = r#"
        use core::convert::TryFrom;
        #[test]
        fn t_array_try_from_good() {
            type Array = [u8; 3];
            let mut array: Array = [0; 3];
            let slice: &[u8] = &array[..];
            let result = <&Array>::try_from(slice);
            assert_eq!(&array, result.unwrap());
            let result = <Array>::try_from(slice);
            assert_eq!(&array, &result.unwrap());
            let mut_slice: &mut [u8] = &mut array[..];
            let result = <&mut Array>::try_from(mut_slice);
            assert_eq!(&[0; 3], result.unwrap());
        }
    "#;
    let out = lift_file(&parse(good), "coretests/array/try_from_literal_good.rs");
    assert!(
        out.assertions_lifted >= 3 && out.assertions_refused == 0,
        "array try_from over a literal-backed slice must lift: lifted={} refused={} skips={:?}",
        out.assertions_lifted,
        out.assertions_refused,
        out.skip_reasons
    );
    for (i, decl) in out.decls.iter().enumerate() {
        if let Some(sat) = z3_verdict(&inv_json(decl), &format!("array_try_from_good_{i}")) {
            assert!(sat, "good array try_from literal equality must be SAT");
        }
    }

    let bad = r#"
        use core::convert::TryFrom;
        #[test]
        fn t_array_try_from_bad() {
            type Array = [u8; 3];
            let mut array: Array = [0; 3];
            let slice: &[u8] = &array[..];
            let result = <&Array>::try_from(slice);
            assert_eq!(&[1u8, 0, 0], result.unwrap());
        }
    "#;
    let out = lift_file(&parse(bad), "coretests/array/try_from_literal_bad.rs");
    assert_eq!(out.assertions_lifted, 1, "{:?}", out.skip_reasons);
    if let Some(sat) = z3_verdict(&inv_json(single_warranted_decl(&out)), "array_try_from_bad") {
        assert!(
            !sat,
            "wrong expected array for literal-backed try_from must be z3-UNSAT"
        );
    }
}

#[test]
fn array_try_from_macro_repeat_lifts_source_audit_locus() {
    let src = r#"
        use core::convert::TryFrom;
        #[test]
        fn array_try_from() {
            macro_rules! test {
                ($($N:expr)+) => {
                    $({
                        type Array = [u8; $N];
                        let mut array: Array = [0; $N];
                        let slice: &[u8] = &array[..];

                        let result = <&Array>::try_from(slice);
                        assert_eq!(&array, result.unwrap());

                        let result = <Array>::try_from(slice);
                        assert_eq!(&array, &result.unwrap());

                        let mut_slice: &mut [u8] = &mut array[..];
                        let result = <&mut Array>::try_from(mut_slice);
                        assert_eq!(&[0; $N], result.unwrap());

                        let mut_slice: &mut [u8] = &mut array[..];
                        let result = <Array>::try_from(mut_slice);
                        assert_eq!(&array, &result.unwrap());
                    })+
                }
            }
            test! { 0 1 2 3 }
        }
    "#;
    let out = lift_file(&parse(src), "coretests/array/array_try_from_macro.rs");
    assert!(
        out.assertions_lifted > 0,
        "array_try_from macro locus must lift at least one assertion; lifted={} refused={} skips={:?} warnings={:?}",
        out.assertions_lifted,
        out.assertions_refused,
        out.skip_reasons,
        out.warnings
    );
}

